  ["A bounty is out on {E}! Kill it within {N} seconds to earn a chest."] = "\002\001被悬赏了！在\001\001秒内击杀它即可获得一个箱子。",
  ["A bubble that blocks the next big hit"] = "抵挡下一次重击的气泡",
  ["A corrupted forest full of demons. Lord Kazzak and Kroshius lead the stages."] = "恶魔盘踞的被腐蚀森林。卡扎克领主和克罗修斯率领着各个战场。",
  ["A crew of demons at your side, afflictions that grow with time, and fel fire that rains on the pack."] = "一队恶魔随侍在侧，诅咒随时间增长，邪能之火倾泻敌群。",
  ["A crew of demons out at once: Imp, Voidwalker, Succubus and Felhunter."] = "一整队恶魔同时出战：小鬼、虚空行者、魅魔与恶魔猎犬。",
  ["A dark forest where the dead walk. Stitches, Morbent Fel or Eliza leads the stage."] = "死者游荡的黑暗森林。缝合怪、莫本斯\183费尔或伊莉莎率领着这片战场。",
  ["A demon portal opens! Destroy it before it closes."] = "一道恶魔传送门开启了！在它关闭之前摧毁它。",
  ["A golden bubble forms around you and blocks the next enemy hit that would take more than 5% of your maximum health, then bursts, dealing Holy damage to every enemy within 10 yards."] = "一个金色气泡环绕你，抵挡敌人的下一次伤害超过\001\001%最大生命值的攻击，然后爆裂，对\001\002码内的所有敌人造成神圣伤害。",
  ["A golden bubble forms around you and blocks the next enemy hit that would take more than 5% of your maximum health."] = "一个金色气泡环绕你，抵挡敌人的下一次伤害超过\001\001%最大生命值的攻击。",
  ["A golden bubble forms around you and blocks the next enemy hit that would take more than 5% of your maximum health. Falling below 30% health makes you immune to damage for 2 sec, at most once every 30 sec."] = "一个金色气泡环绕你，抵挡敌人的下一次伤害超过\001\001%最大生命值的攻击。生命值降至\001\002%以下时，使你免疫伤害\001\003秒，每\001\004秒至多触发一次。",
  ["A kodo caravan is passing through! Keep the raiders off it until it gets across."] = "一支科多兽商队正在经过！护送它穿越这片区域，别让袭击者靠近。",
  ["A meteor falls on the largest group of enemies, dealing heavy Fire damage and 2 stacks of Burning to enemies within 8 yards. Its crater burns for 4 sec, adding 1 stack of Burning every sec to enemies within 5 yards."] = "一颗陨石坠落砸向最大的敌群，对其\001\001码内的敌人造成高额火焰伤害并施加\001\002层燃烧。陨坑燃烧\001\003秒，每秒对\001\004码内的敌人施加\001\005层燃烧。",
  ["A pillar of fire on the largest group"] = "在最大敌群上召唤火柱",
  ["A primal crater ruled by giant beasts. King Mosh or the Gorishi Hive Queen leads the stage."] = "巨兽统治的蛮荒环形山。莫什王或戈里希虫巢女王率领着这片战场。",
  ["A ring of light goes off 3 times over 2 sec, each hitting every enemy within 16 yards of you for Holy damage and healing you for 0.5% of your maximum health per enemy hit, up to 2%."] = "在\001\001秒内接连爆发\001\002次光环，每次击中你\001\003码内的所有敌人，造成神圣伤害，并每命中一个敌人为你恢复\001\004%最大生命值，最多\001\005%。",
  ["A ring of light hits every enemy within 16 yards of you for Holy damage and heals you for 0.5% of your maximum health per enemy hit, up to 2%."] = "一道光环击中你\001\001码内的所有敌人，造成神圣伤害，并每命中一个敌人为你恢复\001\002%最大生命值，最多\001\003%。",
  ["A ring of light hits every enemy within 16 yards of you for Holy damage, up to 100% more the farther they are, and heals you for 0.5% of your maximum health per enemy hit, up to 2%."] = "一道光环击中你\001\001码内的所有敌人，造成神圣伤害，距离越远伤害越高，最多提高\001\002%，并每命中一个敌人为你恢复\001\003%最大生命值，最多\001\004%。",
  ["A ring of light that heals you"] = "治愈你的圣光圆环",
  ["A shapeshifter that changes between Moonkin, Cat, Bear and Tree of Life. Every spell works in every form, and the right form makes it 30% stronger."] = "在枭兽、猎豹、巨熊与生命之树之间切换形态的变形者。每个法术在任何形态下都有效，而正确的形态使其效果提高\001\001%。",
  ["A shield that makes you faster"] = "使你更快的护盾",
  ["A shot that pierces a whole line"] = "贯穿整条直线的射击",
  ["A spirit wolf fights for you, biting for damage. Every 15 sec it howls, and your other pets deal double damage to all enemies in front for 6 sec."] = "一只灵魂之狼为你而战，撕咬造成伤害。它会每隔\001\001秒嚎叫一次，使你的其他宠物对前方所有敌人造成的伤害翻倍，持续\001\002秒。",
  ["A spirit wolf fights for you, biting for damage. Every 15 sec it howls: your other pets deal double damage to all enemies in front for 6 sec, and a Boar, Bear or Wyvern joins for 8 sec. The Boar charges through the largest group, the Bear mauls and leaves enemies bleeding, the Wyvern makes your pets deal 20% more damage."] = "一只灵魂之狼为你而战，撕咬造成伤害。它会每隔\001\001秒嚎叫一次：使你的其他宠物对前方所有敌人造成的伤害翻倍，持续\001\002秒，并有一头野猪、熊或双足飞龙加入，持续\001\003秒。野猪会冲撞最大的敌群，熊会重击并使敌人流血，双足飞龙使你的宠物造成的伤害提高\001\004%。",
  ["A spirit wolf fights for you, biting for damage. Every 15 sec it howls: your other pets deal double damage to all enemies in front for 6 sec. Each kill your pets make meanwhile adds 0.5 sec, up to 10 sec left."] = "一只灵魂之狼为你而战，撕咬造成伤害。它会每隔\001\001秒嚎叫一次：使你的其他宠物对前方所有敌人造成的伤害翻倍，持续\001\002秒。期间你的宠物每击杀一个敌人，效果延长\001\003秒，最多延长至\001\004秒。",
  ["A spirit wolf that empowers your pets"] = "强化你宠物的灵魂之狼",
  ["A stampede is coming! Get out of the way!"] = "兽群狂奔而来！快躲开！",
  ["A storm on the largest group"] = "在最大敌群上掀起风暴",
  ["A storm rages over the largest group of enemies for 4 sec, dealing Nature damage every sec and Dazing them. Empowered in Moonkin Form."] = "风暴在最大的敌群上空肆虐\001\001秒，每秒造成自然伤害并使其眩晕。枭兽形态下获得强化。",
  ["A storm rages over the largest group of enemies for 4 sec, dealing Nature damage every sec and Dazing them. Empowered in Moonkin Form. Every 2 sec, the storm applies Moonfire to enemies inside."] = "风暴在最大的敌群上空肆虐\001\001秒，每秒造成自然伤害并使其眩晕。枭兽形态下获得强化。每\001\002秒，风暴会使其中的敌人染上月火。",
  ["A storm rages over the largest group of enemies for 4 sec, dealing Nature damage every sec and Dazing them. Empowered in Moonkin Form. When the storm ends, it bursts for double damage and knocks enemies back."] = "风暴在最大的敌群上空肆虐\001\001秒，每秒造成自然伤害并使其眩晕。枭兽形态下获得强化。风暴结束时爆发，造成双倍伤害并击退敌人。",
  ["A storm rages over the largest group of enemies for 4 sec, dealing Nature damage every sec to enemies within 8 yards and leaving them Dazed. Empowered in Moonkin Form."] = "风暴在最大的敌群上空肆虐\001\001秒，每秒对\001\002码内的敌人造成自然伤害并使其眩晕。枭兽形态下获得强化。",
  ["A stronger version of a regular enemy, with more health and harder hits."] = "普通敌人的强化版本，生命值更高，攻击更痛。",
  ["A sunken swamp around the Temple of Atal'Hakkar. The Avatar of Hakkar, Jammal'an the Prophet or Morphaz leads the stage."] = "阿塔哈卡神庙周围的沉陷沼泽。哈卡的化身、先知迦玛兰或莫尔法兹率领着这片战场。",
  ["A swarm is coming!"] = "虫群来袭！",
  ["A totem that heals you"] = "治疗你的图腾",
  ["A totem that hurls fire"] = "掷出火焰的图腾",
  ["A totem that pulses fire around you"] = "向四周喷发火焰的图腾",
  ["A training dummy stands ready."] = "一个训练木桩已就绪。",
  ["A trap that explodes and burns the ground"] = "爆炸并灼烧地面的陷阱",
  ["A trap that slows the pack"] = "使敌群减速的陷阱",
  ["A treasure goblin appeared! Catch it before it gets away!"] = "一只财宝地精出现了！在它逃走之前抓住它！",
  ["A wave of fire blasts all enemies within 10 yards of you, dealing Fire damage, 10% more per Burning stack, up to 30 stacks. Every Burning enemy it hits erupts for 40% damage within 5 yards."] = "一道火浪轰击你\001\001码内的所有敌人，造成火焰伤害，每层燃烧使伤害提高\001\002%，最多计算\001\003层。被击中的每个燃烧敌人都会喷发，对\001\004码内的敌人造成\001\005%的伤害。",
  ["A {E} training dummy stands ready."] = "一个\002\001训练木桩已就绪。",
  ["Absorb"] = "吸收量",
  ["Absorbed"] = "已吸收",
  ["Account"] = "账号",
  ["Acolyte"] = "侍僧",
  ["Adds a Shield of 10% of your maximum health that lasts until it absorbs damage, stacking up to 50%."] = "获得一层护盾，可吸收相当于\001\001%最大生命值的伤害，存留直至吸收伤害，最多叠加至\001\002%。",
  ["Adds a Shield of 10% of your maximum health that lasts until it absorbs damage. Each hit it absorbs sends out a shockwave, dealing damage to all enemies within 8 yards of you, at most once every 0.5 sec."] = "获得一层护盾，可吸收相当于\001\001%最大生命值的伤害，存留直至吸收伤害。护盾每吸收一次攻击就会发出一道冲击波，对你\001\002码内的所有敌人造成伤害，每\001\003秒至多触发一次。",
  ["Adds a Shield of 10% of your maximum health that lasts until it absorbs damage. While you hold any Shield, spikes strike all enemies within 8 yards of you for damage every sec."] = "获得一层护盾，可吸收相当于\001\001%最大生命值的伤害，存留直至吸收伤害。只要你持有任意护盾，尖刺就会每秒打击你\001\002码内的所有敌人，造成伤害。",
  ["Adept"] = "行家",
  ["Adjust"] = "调整",
