  ["Affliction"] = "痛苦",
  ["Affliction spells deal 3% more damage."] = "痛苦系法术造成的伤害提高\001\001%。",
  ["Afflicts the 3 enemies farthest from you within 35 yards with 6 stacks of Decay and 1 stack of Shadow Vulnerability."] = "使\001\001码内离你最远的\001\002个敌人染上\001\003层腐朽和\001\004层暗影易伤。",
  ["Afflicts the 3 enemies farthest from you within 35 yards with 6 stacks of Decay."] = "使\001\001码内离你最远的\001\002个敌人染上\001\003层腐朽。",
  ["Afflicts the 3 enemies farthest from you within 35 yards with 6 stacks of Decay. Your Decay heals you for 2% of its damage, up to 1% of your maximum health a sec."] = "使\001\001码内离你最远的\001\002个敌人染上\001\003层腐朽。你的腐朽所造成伤害的\001\004%会为你恢复生命值，每秒最多恢复\001\005%最大生命值。",
  ["After 4 sec without being hit, regain 1% of your health every second."] = "在\001\001秒内未受到攻击后，每秒恢复\001\002%生命值。",
  ["After standing still for 1 sec, regain 1% of your health every second. Copies stack up to 3%."] = "原地站立\001\001秒后，每秒恢复\001\002%生命值。效果最多叠加至\001\003%。",
  ["After you are hit, take no damage for 0.5 sec. 8 sec cooldown, 15% shorter per additional copy."] = "你被击中后的\001\001秒内不会受到伤害。冷却时间\001\002秒，每多持有一张，冷却时间缩短\001\003%。",
