  ["Binds the 3 strongest enemies nearby, elites first, for 2 sec. They take Holy damage when bound and every sec while bound. Bosses and mini-bosses cannot be bound but still take the first hit."] = "束缚附近最强的\001\001个敌人，优先选择精英，持续\001\002秒。敌人们被束缚时以及束缚期间每秒受到神圣伤害。首领和小首领无法被束缚，但仍会受到初次打击。",
  ["Binds the strongest enemy"] = "束缚最强的敌人",
  ["Binds the strongest enemy nearby, elites first, for 2 sec. It takes Holy damage when bound and every sec while bound, and 30% more damage from everything. Bosses and mini-bosses cannot be bound but still take the first hit."] = "束缚附近最强的敌人，优先选择精英，持续\001\001秒。敌人被束缚时以及束缚期间每秒受到神圣伤害，且受到的所有伤害提高\001\002%。首领和小首领无法被束缚，但仍会受到初次打击。",
  ["Binds the strongest enemy nearby, elites first, for 2 sec. It takes Holy damage when bound and every sec while bound. Bosses and mini-bosses cannot be bound but still take the first hit."] = "束缚附近最强的敌人，优先选择精英，持续\001\001秒。敌人被束缚时以及束缚期间每秒受到神圣伤害。首领和小首领无法被束缚，但仍会受到初次打击。",
  ["Blackcrow"] = "黑鸦",
  ["Blackhand's Breadth"] = "黑手的宽厚",
  ["Blackout"] = "黑暗降临",
  ["Blackrock orcs, black dragonkin"] = "黑石兽人、黑龙人",
  ["Blade Dancer"] = "剑舞者",
  ["Blade Flurry"] = "剑刃乱舞",
  ["Blade Flurry recharges 8% faster."] = "剑刃乱舞的充能速度加快\001\001%。",
  ["Bladestorm"] = "剑刃风暴",
  ["Blast Wave"] = "冲击波",
  ["Blastershot Launcher"] = "爆能发射器",
  ["Blasts all enemies within 10 yards of you with arcane energy, dealing Arcane damage. Also goes off where you land after each Blink."] = "以奥术能量轰击你\001\001码内的所有敌人，造成奥术伤害。每次闪现落地的位置也会引发爆炸。",
  ["Blasts all enemies within 10 yards of you with arcane energy, dealing Arcane damage. Also goes off where you land after each Blink. A blast leaves a time bubble for 10 sec: normal enemies inside move 60% slower and all enemies inside take 15% more damage."] = "以奥术能量轰击你\001\001码内的所有敌人，造成奥术伤害。每次闪现落地的位置也会引发爆炸。爆炸会留下一个时间泡，持续\001\002秒：泡内的普通敌人移动速度降低\001\003%，泡内所有敌人受到的伤害提高\001\004%。",
  ["Blasts all enemies within 10 yards of you with arcane energy, dealing Arcane damage. Also goes off where you land after each Blink. Each blast instantly casts one of your other spells, at most once every 0.5 sec."] = "以奥术能量轰击你\001\001码内的所有敌人，造成奥术伤害。每次闪现落地的位置也会引发爆炸。每次爆炸都会立即施放你的一个其他法术，每\001\002秒至多触发一次。",
  ["Blasts all enemies within 10 yards of you with frost, dealing Frost damage and applying 3 stacks of Chill."] = "以寒霜轰击你\001\001码内的所有敌人，造成冰霜伤害并施加\001\002层冰寒。",
  ["Blasts all enemies within 10 yards of you with frost, dealing Frost damage and applying 3 stacks of Chill. Each enemy it Freezes adds a Shield of 1% of your maximum health, up to 15% per cast."] = "以寒霜轰击你\001\001码内的所有敌人，造成冰霜伤害并施加\001\002层冰寒。每冻结一个敌人就获得一层护盾，可吸收\001\003%最大生命值的伤害，每次施法最多叠加至\001\004%。",
  ["Blasts all enemies within 8 yards of you for damage, set off by your other spells instead of a cooldown. Enemies hit attack 20% slower for 6 sec. Haste lowers how many casts it needs, down to 4."] = "轰击你\001\001码内的所有敌人，造成伤害，由你的其他法术触发而非冷却时间。被击中的敌人攻击速度降低\001\002%，持续\001\003秒。急速会降低触发所需的施法次数，最低为\001\004次。",
  ["Blasts all enemies within 8 yards of you for damage. Enemies hit attack 20% slower and deal 20% less damage for 6 sec. Heals you for 0.3% of your maximum health per enemy hit, up to 2%."] = "轰击你\001\001码内的所有敌人，造成伤害。被击中的敌人攻击速度降低\001\002%，造成的伤害降低\001\003%，持续\001\004秒。每命中一个敌人为你恢复\001\005%最大生命值，最多\001\006%。",
  ["Blasts all enemies within 8 yards of you for damage. Enemies hit attack 20% slower for 6 sec."] = "轰击你\001\001码内的所有敌人，造成伤害。被击中的敌人攻击速度降低\001\002%，持续\001\003秒。",
  ["Blasts nearby enemies and slows their attacks"] = "轰击附近敌人并降低其攻击速度",
  ["Blasts the 3 enemies with the most Burning, dealing Fire damage, 10% more per Burning stack, up to 30 stacks."] = "轰击燃烧层数最多的\001\001个敌人，造成火焰伤害，每层燃烧使伤害提高\001\002%，最多计算\001\003层。",
  ["Blasts the 3 enemies with the most Burning, dealing Fire damage, 10% more per Burning stack, up to 30 stacks. Its first critical strike each cast fires your Pyroblast at once, or a Pyroblast at the target if you have none."] = "轰击燃烧层数最多的\001\001个敌人，造成火焰伤害，每层燃烧使伤害提高\001\002%，最多计算\001\003层。每次施法的第一次致命一击会立即触发你的炎爆术，若你没有炎爆术，则改为对目标施放一发炎爆术。",
  ["Blasts the enemy with the most Decay for Shadow damage. Every enemy within 8 yards of it gains as many Decay stacks as it has, up to 10, then its own Decay deals all its remaining damage at once."] = "轰击腐朽层数最多的敌人，造成暗影伤害。其\001\001码内的所有敌人都会获得与其相同的腐朽层数，最多\001\002层，随后其自身的腐朽会立即造成所有剩余伤害。",
  ["Blasts the enemy with the most Decay for Shadow damage. Every enemy within 8 yards of it gains as many Decay stacks as it has, up to 10."] = "轰击腐朽层数最多的敌人，造成暗影伤害。其\001\001码内的所有敌人都会获得与其相同的腐朽层数，最多\001\002层。",
  ["Blasts the enemy with the most Decay for Shadow damage. Every enemy within 8 yards of it takes half and gains as many Decay stacks as it has, up to 10."] = "轰击腐朽层数最多的敌人，造成暗影伤害。其\001\001码内的所有敌人受到一半伤害，并获得与其相同的腐朽层数，最多\001\002层。",
  ["Blasts the most burning enemies"] = "轰击燃烧最烈的敌人",
