  ["Burns every enemy close to you"] = "灼烧你附近的所有敌人",
  ["Burns every enemy within 10 yards of you with holy light, dealing Holy damage every sec. Enemies that strike you take double."] = "以圣光灼烧你\001\001码内的所有敌人，每秒造成神圣伤害。攻击你的敌人受到双倍伤害。",
  ["Burns every enemy within 10 yards of you with holy light, dealing Holy damage every sec. Enemies that strike you take double. You take 10% less damage."] = "以圣光灼烧你\001\001码内的所有敌人，每秒造成神圣伤害。攻击你的敌人受到双倍伤害。你受到的伤害降低\001\002%。",
  ["Burns every enemy within 14 yards of you with holy light, dealing Holy damage every sec. Enemies that strike you take double."] = "以圣光灼烧你\001\001码内的所有敌人，每秒造成神圣伤害。攻击你的敌人受到双倍伤害。",
  ["Burns the 2 nearest enemies for Arcane damage and applies 1 stack of Moonfire. Empowered in Moonkin Form."] = "灼烧最近的\001\001个敌人，造成奥术伤害并施加\001\002层月火。枭兽形态下获得强化。",
  ["Burns the 2 nearest enemies for Arcane damage and applies 1 stack of Moonfire. Empowered in Moonkin Form. Every 10th stack of Moonfire on an enemy calls down a Full Moon, dealing Arcane damage to it and nearby enemies."] = "灼烧最近的\001\001个敌人，造成奥术伤害并施加\001\002层月火。枭兽形态下获得强化。敌人身上每叠至第\001\003层月火，就会召下一轮满月，对其及附近敌人造成奥术伤害。",
  ["Burns the 2 nearest enemies for Arcane damage and applies 1 stack of Moonfire. Empowered in Moonkin Form. Moonfire spreads to up to 3 nearby enemies of each target."] = "灼烧最近的\001\001个敌人，造成奥术伤害并施加\001\002层月火。枭兽形态下获得强化。月火会蔓延至每个目标附近最多\001\003个敌人。",
  ["Burns the 2 nearest enemies with moonlight for Arcane damage and 1 stack of Moonfire, choosing enemies without Moonfire first. Empowered in Moonkin Form."] = "以月光灼烧最近的\001\001个敌人，造成奥术伤害并施加\001\002层月火，优先选择没有月火的敌人。枭兽形态下获得强化。",
  ["Burns the strongest enemy"] = "灼烧最强的敌人",
