  ["Buy rank "] = "购买等级 ",
  ["Buy {E} at the Spellbook to unlock it."] = "在法术书中购买\002\001即可解锁。",
  ["Buys gear and upgrades at the Inn. You keep it between runs."] = "在旅店购买装备和升级。远征结束后保留。",
  ["Call Pet"] = "召唤宠物",
  ["Call Pet and Pack Leader deal 3% more damage."] = "召唤宠物和狼群首领造成的伤害提高\001\001%。",
  ["Call Pet summons 1 additional beast."] = "召唤宠物额外召唤\001\001头野兽。",
  ["Call of Flame"] = "火焰召唤",
  ["Call of Thunder"] = "雷霆召唤",
  ["Calls down 3 pillars of fire one after another through the largest group of enemies, each dealing Fire damage and applying 2 stacks of Burning."] = "在最大的敌群中接连降下\001\001根火柱，每根造成火焰伤害并施加\001\002层燃烧。",
  ["Calls down a pillar of fire on the largest group of enemies, dealing Fire damage and applying 2 stacks of Burning."] = "在最大的敌群上空召唤一根火柱，造成火焰伤害并施加\001\001层燃烧。",
  ["Calls down a pillar of fire on the largest group of enemies, dealing Fire damage and applying 2 stacks of Burning. The ground burns for 6 sec, adding 1 stack of Burning every sec to enemies within 8 yards."] = "在最大的敌群上空召唤一根火柱，造成火焰伤害并施加\001\001层燃烧。地面燃烧\001\002秒，每秒对\001\003码内的敌人施加\001\004层燃烧。",
  ["Calls down starlight on the strongest enemy for heavy Arcane damage. Empowered in Moonkin Form."] = "召下星光打击最强的敌人，造成高额奥术伤害。枭兽形态下获得强化。",
  ["Calls down starlight on the strongest enemy for heavy Arcane damage. Empowered in Moonkin Form. Enemies afflicted by Moonfire have a chance to be struck by Shooting Stars."] = "召下星光打击最强的敌人，造成高额奥术伤害。枭兽形态下获得强化。中了月火的敌人有几率被流星击中。",
  ["Calls down starlight on the strongest enemy for heavy Arcane damage. Empowered in Moonkin Form. The starlight bursts, dealing 15% damage to nearby enemies and applying Moonfire."] = "召下星光打击最强的敌人，造成高额奥术伤害。枭兽形态下获得强化。星光会迸发，对附近的敌人造成\001\001%的伤害并施加月火。",
  ["Calls down starlight on the strongest enemy within 30 yards for heavy Arcane damage. Empowered in Moonkin Form."] = "召下星光打击\001\001码内最强的敌人，造成高额奥术伤害。枭兽形态下获得强化。",
  ["Calms the air around you for 4 sec. Every sec, deals Nature damage to every enemy within 10 yards and heals you for 0.5% of your maximum health. Empowered in Tree of Life."] = "使你周围的空气平静\001\001秒。每秒对\001\002码内的所有敌人造成自然伤害，并为你恢复\001\003%最大生命值。生命之树形态下获得强化。",
  ["Calms the air for 4 sec. Every sec, deals Nature damage to nearby enemies and heals you for 0.5% of your maximum health. Empowered in Tree of Life."] = "使空气平静\001\001秒。每秒对附近的敌人造成自然伤害，并为你恢复\001\002%最大生命值。生命之树形态下获得强化。",
  ["Calms the air for 4 sec. Every sec, deals Nature damage to nearby enemies and heals you for 0.5% of your maximum health. Empowered in Tree of Life. Each pulse reaches 3 yards further."] = "使空气平静\001\001秒。每秒对附近的敌人造成自然伤害，并为你恢复\001\002%最大生命值。生命之树形态下获得强化。每跳的波及范围扩大\001\003码。",
  ["Calms the air for 4 sec. Every sec, deals Nature damage to nearby enemies and heals you for 0.5% of your maximum health. Empowered in Tree of Life. Excess healing deals up to 60% additional damage to nearby enemies."] = "使空气平静\001\001秒。每秒对附近的敌人造成自然伤害，并为你恢复\001\002%最大生命值。生命之树形态下获得强化。溢出的治疗会转化为额外伤害，对附近敌人最多造成\001\003%的额外伤害。",
