  ["Corruptor"] = "腐蚀者",
  ["Corrupts the 2 nearest enemies with 1 stack of Decay, or 2 on an enemy without Decay."] = "腐蚀最近的\001\001个敌人，施加\001\002层腐朽，若敌人身上没有腐朽则施加\001\003层。",
  ["Corrupts the 2 nearest enemies with 1 stack of Decay. Corrupted enemies explode on death, adding 1 stack of Decay to enemies within 6 yards. Explosion kills explode too, up to 2 in a row."] = "腐蚀最近的\001\001个敌人，施加\001\002层腐朽。被腐蚀的敌人死亡时会爆炸，对其\001\003码内的敌人施加\001\004层腐朽。被爆炸击杀的敌人也会爆炸，最多连锁\001\005次。",
  ["Corrupts the 2 nearest enemies with 1 stack of Decay. Every 6 sec, each corrupted enemy within 30 yards takes 3 sec of its Decay damage at once and keeps its stacks."] = "腐蚀最近的\001\001个敌人，施加\001\002层腐朽。每\001\003秒，\001\004码内每个被腐蚀的敌人会立即承受\001\005秒的腐朽伤害，并保留层数。",
