  ["Dungeon"] = "地下城",
  ["Dungeon challenge"] = "地下城挑战",
  ["Dungeon mode plays every stage inside "] = "地下城模式的每个阶段都在",
  ["Dungeon room"] = "地下城房间",
  ["Dungeon: every stage takes place inside "] = "地下城：每个阶段都在",
  ["Duration"] = "持续时间",
  ["Durgan now sells Heroic gear as well. It is a lot stronger than Normal gear, so look here before you spend your gold."] = "德尔冈现在也出售英雄装备。它比普通装备强大得多，花钱前先看看这里。",
  ["Durgan now sells Mythic gear, the strongest he has. Look here before you spend your gold."] = "德尔冈现在出售史诗装备，这是他最强的货色。花钱前先看看这里。",
  ["Duskwood"] = "暮色森林",
  ["Dwarf"] = "矮人",
  ["Each Blink grants a Shield of 3% of your maximum health."] = "每次闪现都会获得一层护盾，可吸收相当于\001\001%最大生命值的伤害。",
  ["Each dash leaves one of each of your traps behind, armed at once. Your maximum health is reduced by 15%."] = "每次冲刺都会在身后留下你每种陷阱各一个，并立即生效。你的最大生命值降低\001\001%。",
  ["Each of your totem spells plants 1 additional totem. Your Power is reduced by 15%."] = "你的每个图腾法术都会额外插入\001\001根图腾。你的力量降低\001\002%。",
  ["Each point is worth a little less than the last, up to at most "] = "每一点的效果都比上一点略低，最多",
  ["Each rank: "] = "每级：",
  ["Each run starts again at level 1."] = "每次远征都从\001\001级重新开始。",
  ["Each stack deals Arcane damage every sec. Each new stack refreshes all stacks to their full duration, up to 30 stacks. When a moonfired enemy dies, half of its stacks spread to the 2 nearest enemies within 8 yards."] = "每层每秒造成奥术伤害。每层新叠加都会将所有层数的持续时间刷新至上限，最多\001\001层。中了月火的敌人死亡时，一半的层数会蔓延至\001\002码内最近的\001\003个敌人。",
  ["Each stack deals Fire damage every sec. Each new stack refreshes all stacks to their full duration, up to 30 stacks. When a burning enemy dies, half of its stacks spread to the 2 nearest enemies within 8 yards."] = "每层每秒造成火焰伤害。每层新叠加都会将所有层数的持续时间刷新至上限，最多\001\001层。燃烧中的敌人死亡时，一半的层数会蔓延至\001\002码内最近的\001\003个敌人。",
  ["Each stack deals Nature damage every sec. Each new stack refreshes all stacks to their full duration, up to 30 stacks. When a poisoned enemy dies, half of its stacks spread to the 2 nearest enemies within 8 yards."] = "每层每秒造成自然伤害。每层新叠加都会将所有层数的持续时间刷新至上限，最多\001\001层。中毒的敌人死亡时，一半的层数会蔓延至\001\002码内最近的\001\003个敌人。",
  ["Each stack deals Physical damage every sec. Each new stack refreshes all stacks to their full duration, up to 30 stacks. When a bleeding enemy dies, half of its stacks spread to the 2 nearest enemies within 8 yards."] = "每层每秒造成物理伤害。每层新叠加都会将所有层数的持续时间刷新至上限，最多\001\001层。流血中的敌人死亡时，一半的层数会蔓延至\001\002码内最近的\001\003个敌人。",
  ["Each stack deals Shadow damage every sec. A stack's damage grows by a quarter of its starting damage every sec it stays on, up to triple after 8 sec. One curse per enemy."] = "每层每秒造成暗影伤害。层数停留在敌人身上的每秒，其伤害都会增长起始伤害的四分之一，\001\001秒后最多增长至三倍。每个敌人只能承受一个诅咒。",
  ["Each stack deals Shadow damage every sec. Each new stack refreshes all stacks to their full duration, up to 30 stacks. When a decaying enemy dies, half of its stacks spread to the 2 nearest enemies within 8 yards."] = "每层每秒造成暗影伤害。每层新叠加都会将所有层数的持续时间刷新至上限，最多\001\001层。腐朽的敌人死亡时，一半的层数会蔓延至\001\002码内最近的\001\003个敌人。",
  ["Earth Shield"] = "大地之盾",
  ["Earth Shock"] = "大地震击",
  ["Earth Shock stuns normal enemies for 1 sec. Once per enemy every 6 sec."] = "大地震击会使普通敌人昏迷\001\001秒。每个敌人每\001\002秒一次。",
