  ["Elementalist"] = "元素学者",
  ["Elites"] = "精英",
  ["Elites and bosses dodge your hits less often. Normal enemies never dodge."] = "精英和首领更少闪避你的攻击。普通敌人从不闪避。",
  ["Elites and mini-bosses sometimes drop one. It lets you escape the run early and takes you back to the Inn with 1 item from your Extraction Vault."] = "精英和小首领有时会掉落炉石。它可以让你提前撤离远征，并带你和提取保险库中的\001\001件物品一起返回旅店。",
  ["Elites are closing in!"] = "精英正在逼近！",
  ["Elites have 1 additional affix. +20% gold."] = "精英额外带有\001\001个词缀。金币提高\001\002%。",
  ["Elites you kill drop a power-up."] = "你击杀的精英会掉落一个强化效果。",
