  ["Enclosed raid"] = "封闭团本",
  ["End this run?"] = "结束本次远征？",
  ["End this run? It counts as a defeat. You keep the gold and Darkmoon Tickets you earned, but loot you haven't extracted is lost."] = "结束本次远征？这将计为一次失败。你保留已获得的金币和暗月奖券，但尚未提取的战利品将会丢失。",
  ["Endless Flurry"] = "无尽乱舞",
  ["Endless dry plains full of Razormane and Kolkar raiders. Charlga Razorflank, Agathelos the Raging or Mutanus the Devourer leads the stage."] = "遍布剃刀沼泽野猪人和科卡尔劫掠者的无尽干草原。查尔加\183剃刀鬃、狂怒的阿加塞洛斯或吞噬者穆坦努斯率领着这片战场。",
  ["Endurance Training"] = "耐力训练",
  ["Enemies deal 50% more damage. +25% gold."] = "敌人造成的伤害提高\001\001%。金币提高\001\002%。",
  ["Enemies deal less damage to you."] = "敌人对你造成的伤害降低。",
  ["Enemies drop 50% more gold, and loot is one quality higher."] = "敌人掉落的金币提高\001\001%，战利品品质提高一级。",
  ["Enemies have 180% more health and deal 60% more damage.^Casters lead their shots precisely.^Bosses lead their spells precisely and get even more attacks.^25% of enemies are Veterans: tougher and worth more.^Elites have 3 affixes and dodge even more. Chargers charge more often."] = "敌人的生命值提高\001\001%，造成的伤害提高\001\002%。^施法者的射击会精确预判。^首领的法术精确预判且攻击更频繁。^\001\003%的敌人是老兵：更强悍，奖励更高。^精英带有\001\004个词缀且闪避更高。冲锋者冲锋更频繁。",
  ["Enemies have 30% more health and deal 20% more damage."] = "敌人的生命值提高\001\001%，造成的伤害提高\001\002%。",
  ["Enemies have 50% more health. +25% gold."] = "敌人的生命值提高\001\001%。金币提高\001\002%。",
  ["Enemies have 60% more health and deal 30% more damage.^Casters lead their shots slightly more accurately.^Bosses lead their spells more and get extra attacks.^15% of enemies are Veterans: tougher and worth more.^Elites have 2 affixes and dodge more. Chargers charge more often."] = "敌人的生命值提高\001\001%，造成的伤害提高\001\002%。^施法者的射击预判更准。^首领的法术预判更多且攻击更频繁。^\001\003%的敌人是老兵：更强悍，奖励更高。^精英带有\001\004个词缀且闪避更高。冲锋者冲锋更频繁。",
  ["Enemies killed this run."] = "本次远征击杀的敌人。",
  ["Enemies slain"] = "击杀敌人",
  ["Enemies that hit you take 50% of the damage they deal."] = "攻击你的敌人会受到其造成伤害\001\001%的伤害。",
  ["Enemies that strike you take Nature damage, at most 5 times a sec. Empowered in Bear Form."] = "攻击你的敌人受到自然伤害，每秒至多\001\001次。巨熊形态下获得强化。",
  ["Enemies that strike you take Nature damage. Empowered in Bear Form."] = "攻击你的敌人受到自然伤害。巨熊形态下获得强化。",
  ["Enemies that strike you take Nature damage. Empowered in Bear Form. Enemies that strike you are rooted for 1 sec."] = "攻击你的敌人受到自然伤害。巨熊形态下获得强化。攻击你的敌人会被定身\001\001秒。",
  ["Enemies that strike you take Nature damage. Empowered in Bear Form. Thorns also strike all other nearby enemies for 50% damage."] = "攻击你的敌人受到自然伤害。巨熊形态下获得强化。荆棘还会打击附近的所有其他敌人，造成\001\001%的伤害。",
  ["Enemies that strike you take damage"] = "攻击你的敌人将受到伤害",
  ["Enemy Nameplates"] = "敌人姓名板",
  ["Engineering Gloves"] = "工程学手套",
  ["Enhancement"] = "增强",
  ["Enhancement spells deal 3% more damage."] = "增强系法术造成的伤害提高\001\001%。",
  ["Enrage"] = "狂怒",
  ["Enrage grants 5% more Haste."] = "狂怒状态提供的急速提高\001\001%。",
  ["Enrage lasts 1 sec longer."] = "狂怒状态延长\001\001秒。",
  ["Entangling Roots"] = "纠缠根须",
  ["Entangling Roots grasp 1 additional enemy."] = "纠缠根须额外缠绕\001\001个敌人。",
  ["Enter"] = "进入",
  ["Entering the world..."] = "正在进入世界……",
  ["Entrapment"] = "纠缠",
  ["Envenom"] = "毒伤",
  ["Envenom deals 5% more damage."] = "毒伤造成的伤害提高\001\001%。",
  ["Epic"] = "史诗",
  ["Equip"] = "装备",
  ["Equipped"] = "已装备",
  ["Errand Runner"] = "跑腿小子",
  ["Evade"] = "规避",
  ["Evasion"] = "闪避",
  ["Evasion recharges 15% faster."] = "闪避的充能速度加快\001\001%。",
  ["Every 120 sec, every experience orb on the ground flies to you. You can hold only 1."] = "每\001\001秒，地面上的所有经验球都会飞向你。至多持有\001\002张。",
  ["Every 2nd strike from your other Paladin spells releases a burst of light, dealing Holy damage to the target and every enemy within 5 yards of it."] = "你的其他圣骑士法术每\001\001次打击中的第\001\001次会释放一次圣光爆发，对目标及其\001\002码内的所有敌人造成神圣伤害。",
  ["Every 3 sec, lightning strikes up to 8 nearby enemies. Always critically strikes."] = "每\001\001秒，闪电会打击最多\001\002个附近敌人。必定造成致命一击。",
  ["Every 3rd strike bursts with light"] = "每第\001\001次打击爆发圣光",
  ["Every 3rd strike from your other Paladin spells releases a burst of light, dealing Holy damage to the target and every enemy within 5 yards of it and stunning normal and elite enemies for 1 sec."] = "你的其他圣骑士法术每\001\001次打击中的第\001\001次会释放一次圣光爆发，对目标及其\001\002码内的所有敌人造成神圣伤害，并使普通敌人和精英昏迷\001\003秒。",
  ["Every 3rd strike from your other Paladin spells releases a burst of light, dealing Holy damage to the target and every enemy within 5 yards of it."] = "你的其他圣骑士法术每\001\001次打击中的第\001\001次会释放一次圣光爆发，对目标及其\001\002码内的所有敌人造成神圣伤害。",
  ["Every 50 kills, gain 40% Haste for 8 sec."] = "每击杀\001\001个敌人，获得\001\002%急速，持续\001\003秒。",
  ["Every 50 kills, you deal triple damage for 2 sec."] = "每击杀\001\001个敌人，你造成的伤害提高至三倍，持续\001\002秒。",
  ["Every 5th Crusader Strike is a Templar's Verdict, dealing triple damage to every enemy within 5 yards of the target. Your critical strike chance is reduced by 10%."] = "每\001\001次十字军打击中的第\001\001次会变为圣殿骑士的裁决，对目标\001\002码内的所有敌人造成三倍伤害。你的致命一击几率降低\001\003%。",
  ["Every 5th cast of each spell critically strikes every enemy it hits. Your Haste is reduced by 10%."] = "每个法术每\001\001次施放中的第\001\001次会对其命中的所有敌人造成致命一击。你的急速降低\001\002%。",
  ["Every 5th hit hurls free lightning"] = "每第\001\001次命中掷出免费闪电",
  ["Every 5th melee hit hurls a free Lightning Bolt at the 3 nearest enemies, or a Chain Lightning if you have it, dealing Nature damage."] = "每\001\001次近战命中会免费向最近的\001\002个敌人掷出闪电箭，若你拥有闪电链则改为闪电链，造成自然伤害。",
  ["Every 5th melee hit hurls a free Lightning Bolt at the nearest enemy, or a Chain Lightning if you have it, dealing Nature damage and 5 stacks of Static, so it discharges at once."] = "每\001\001次近战命中会免费向最近的敌人掷出闪电箭，若你拥有闪电链则改为闪电链，造成自然伤害并施加\001\002层静电，使其立即放电。",
  ["Every 5th melee hit hurls a free Lightning Bolt at the nearest enemy, or a Chain Lightning if you have it, dealing Nature damage. Melee hits are Windfury Weapon swings, Stormstrike and Feral Spirit bites."] = "每\001\001次近战命中会免费向最近的敌人掷出一道闪电箭，若你拥有闪电链则改为闪电链，造成自然伤害。近战命中包括风怒武器挥击、风暴打击和野性狼魂的撕咬。",
  ["Every 6 sec, a meteor strikes the largest nearby group of enemies."] = "每\001\001秒，一颗陨石砸向附近最大的敌群。",
  ["Every 60 sec, gain 25% Power for 15 sec."] = "每\001\001秒获得\001\002%力量，持续\001\003秒。",
  ["Every Greed Totem taken this run adds a stack."] = "本次远征中每取得一个贪婪图腾，就会叠加一层。",
  ["Every Stacked Deck slot is in use ("] = "所有叠好的牌堆槽位均已用完（",
  ["Every hero starts with "] = "每个英雄初始拥有",
  ["Every hit from your other Paladin spells, splash and area hits included, deals 20% extra as Holy damage, 20% more for each hit on the same enemy, up to 5 times."] = "你的其他圣骑士法术的每次命中，包括溅射和范围命中，都额外造成\001\001%的神圣伤害，对同一敌人的每次命中使该伤害提高\001\002%，最多计算\001\003次。",
  ["Every hit from your other Paladin spells, splash and area hits included, deals 20% extra as Holy damage."] = "你的其他圣骑士法术的每次命中，包括溅射和范围命中，都额外造成\001\001%的神圣伤害。",
  ["Every hit from your other Paladin spells, splash and area hits included, deals 40% extra as Holy damage."] = "你的其他圣骑士法术的每次命中，包括溅射和范围命中，都额外造成\001\001%的神圣伤害。",
  ["Every level brings a choice of 3 upgrades."] = "每升一级都会提供\001\001项强化供选择。",
  ["Every sec, heals you for 0.25% of your maximum health per nearby enemy, up to 5. Empowered in Bear Form."] = "每秒根据附近的敌人数量为你恢复生命值，每个敌人恢复\001\001%最大生命值，最多计算\001\002个。巨熊形态下获得强化。",
  ["Every sec, heals you for 0.25% of your maximum health per nearby enemy, up to 5. Empowered in Bear Form. Each tick also grants a Shield of the same amount, up to 10% of your maximum health."] = "每秒根据附近的敌人数量为你恢复生命值，每个敌人恢复\001\001%最大生命值，最多计算\001\002个。巨熊形态下获得强化。每跳还会获得等量的护盾，最多可吸收\001\003%最大生命值的伤害。",
  ["Every sec, heals you for 0.25% of your maximum health per nearby enemy, up to 5. Empowered in Bear Form. Each tick also mauls up to 5 nearby enemies for damage."] = "每秒根据附近的敌人数量为你恢复生命值，每个敌人恢复\001\001%最大生命值，最多计算\001\002个。巨熊形态下获得强化。每跳还会重殴最多\001\003个附近敌人，造成伤害。",
  ["Every strike from your other Paladin spells heals you for 0.5% of your maximum health, at most 6 times a sec."] = "你的其他圣骑士法术的每次打击都会为你恢复\001\001%最大生命值，每秒至多\001\002次。",
  ["Every strike from your other Paladin spells heals you for 0.5% of your maximum health, at most 6 times a sec. Critical strikes heal triple."] = "你的其他圣骑士法术的每次打击都会为你恢复\001\001%最大生命值，每秒至多\001\002次。致命一击的治疗量提高至三倍。",
  ["Every strike from your other Paladin spells heals you for 0.5% of your maximum health, at most 6 times a sec. Falling below 30% health heals you to full, at most once every 90 sec."] = "你的其他圣骑士法术的每次打击都会为你恢复\001\001%最大生命值，每秒至多\001\002次。生命值降至\001\003%以下时，将你的生命值恢复全满，每\001\004秒至多触发一次。",
  ["Eviscerate"] = "剔骨",
  ["Eviscerate deals 5% more damage."] = "剔骨造成的伤害提高\001\001%。",
  ["Evolution offers let you pick any evolution of that spell."] = "进化选项允许你选择该法术的任意进化方向。",
  ["Evolutions"] = "进化",
  ["Evolutions can be offered 1 rank earlier."] = "进化可以提前\001\001级出现。",
  ["Evolved from "] = "进化自",
  ["Execute"] = "斩杀",
  ["Execute kills normal enemies below 25% health, up from 20%."] = "斩杀可直接击杀生命值低于\001\001%的普通敌人（原为\001\002%）。",
  ["Executioner"] = "刽子手",
  ["Exit Game"] = "退出游戏",
  ["Exorcism"] = "驱邪术",
  ["Exorcism deals 5% more damage."] = "驱邪术造成的伤害提高\001\001%。",
  ["Exorcism recharges 15% faster."] = "驱邪术的充能速度加快\001\001%。",
  ["Exorcism strikes 2 additional enemies, and Art of War can trigger it every 0.5 sec. Your Power is reduced by 15%."] = "驱邪术额外打击\001\001个敌人，且战争艺术可每\001\002秒触发一次。你的力量降低\001\003%。",
  ["Exorcist"] = "驱魔人",
  ["Expedition"] = "远征",
