  ["Fel fire burns every enemy within 8 yards of you, dealing damage. Your demons burn too, hitting enemies within 6 yards of them for half damage."] = "邪能烈焰灼烧你\001\001码内的所有敌人，造成伤害。你的恶魔也会燃烧，对其\001\002码内的敌人造成一半伤害。",
