  ["Field Medic"] = "战地医师",
  ["Fields between Scholomance and the Scarlet camps. Darkmaster Gandling, Jandice Barov or Doctor Theolen Krastinov leads the stage."] = "通灵学院与血色营地之间的田野。黑暗院长加丁、詹迪斯\183巴罗夫或瑟欧伦\183克拉斯托夫医生率领着这片战场。",
  ["Fights in the thick of the horde. Every swing hits all around you, and there is no Rage to manage."] = "冲进敌群中央战斗。每一次挥击都会命中周围的所有敌人，而且无需管理怒气。",
