  ["Fire bolt that leaves enemies Burning"] = "使敌人燃烧的火焰箭",
  ["Fire burns every enemy within 8 yards of you, dealing damage."] = "烈焰灼烧你\001\001码内的所有敌人，造成伤害。",
  ["Fire burns everything around you"] = "烈焰灼烧你周围的一切",
  ["Fire damage over time."] = "持续火焰伤害。",
  ["Fire elementals, core hounds, Molten Giants"] = "火焰元素、熔火恶犬、熔火巨人",
  ["Fire rains on the largest group"] = "火焰之雨倾泻最大敌群",
  ["Fire spells deal 3% more damage."] = "火焰系法术造成的伤害提高\001\001%。",
  ["Fire that leaves enemies Burning"] = "使敌人燃烧的火焰",
  ["Fireball"] = "火球术",
  ["Firelord"] = "炎魔之王",
  ["Firelord's Favor"] = "炎魔之王的恩宠",
  ["Fires 3 arrows in a cone in front of you, dealing damage and applying 2 stacks of Poison."] = "向前方锥形范围内射出\001\001支箭，造成伤害并施加\001\002层中毒。",
  ["Fires 3 arrows in a cone in front of you, dealing damage."] = "向前方锥形范围内射出\001\001支箭，造成伤害。",
  ["Fires 3 arrows in a cone in front of you, dealing damage. Each enemy they kill fires 3 arrows at the nearest enemies within 15 yards, and those kills fire again."] = "向前方锥形范围内射出\001\001支箭，造成伤害。被射杀的每个敌人会向\001\002码内最近的敌人再射出\001\003支箭，被射杀的目标还会继续触发。",
  ["Fires 3 holy bolts at the enemies that struck you last, each dealing Holy damage, hitting enemies within 4 yards for half and healing you for 0.5% of your maximum health. Healing past full health becomes Shield."] = "向最近攻击过你的敌人发射\001\001枚神圣箭，每枚造成神圣伤害，命中其\001\002码内的敌人造成一半伤害，并为你恢复\001\003%最大生命值。溢出满生命值的治疗会转化为护盾。",
  ["Fires 3 holy bolts at the enemies that struck you last, or 5 while you have a Shield, each dealing Holy damage and healing you for 0.5% of your maximum health. Healing past full health becomes Shield."] = "向最近攻击过你的敌人发射\001\001枚神圣箭，持有护盾时改为\001\002枚，每枚造成神圣伤害并为你恢复\001\003%最大生命值。溢出满生命值的治疗会转化为护盾。",
  ["Fires 3 holy bolts at the enemies that struck you last, or the nearest enemies, each dealing Holy damage and healing you for 0.5% of your maximum health. Healing past full health becomes Shield."] = "向最近攻击过你的敌人发射\001\001枚神圣箭，若没有则射向最近的敌人，每枚造成神圣伤害并为你恢复\001\002%最大生命值。溢出满生命值的治疗会转化为护盾。",
  ["Fires a Chaos Bolt at the nearest enemy, dealing damage. Every 4th bolt crits its target and every enemy within 8 yards for 150% damage. Nightfall: enemies that die with your afflictions on them fire a free bolt, at most 1 a sec."] = "向最近的敌人射出一发混沌箭，造成伤害。每\001\001发中的第\001\001发会对其目标及其\001\002码内的敌人造成致命一击，伤害为\001\003%。夜幕：身上带有你的诅咒效果死亡的敌人会触发一发免费暗影箭，每秒至多\001\004发。",
  ["Fires a Shadow Bolt at the nearest enemy, dealing damage. Nightfall: enemies that die with your afflictions on them fire a free bolt, at most 1 a sec, that jumps to 2 nearby enemies for half damage."] = "向最近的敌人射出一发暗影箭，造成伤害。夜幕：身上带有你的诅咒效果死亡的敌人会触发一发免费暗影箭，每秒至多\001\001发，该箭会跳向\001\002个附近敌人，造成一半伤害。",
  ["Fires a Shadow Bolt at the nearest enemy, dealing damage. Nightfall: enemies that die with your afflictions on them fire a free bolt, at most 1 a sec."] = "向最近的敌人射出一发暗影箭，造成伤害。夜幕：身上带有你的诅咒效果死亡的敌人会触发一发免费暗影箭，每秒至多\001\001发。",
  ["Fires a shot that pierces every enemy in a line, dealing damage. Aims at the Marked group, or else the largest group."] = "发射一发贯穿直线上所有敌人的射击，造成伤害。优先瞄准被标记的敌群，其次瞄准最大的敌群。",
  ["Fires a shot that pierces every enemy in a line, dealing damage. Aims at the Marked group, or else the largest group. Each enemy pierced then explodes in turn for 40% of the damage within 4 yards."] = "发射一发贯穿直线上所有敌人的射击，造成伤害。优先瞄准被标记的敌群，其次瞄准最大的敌群。被贯穿的每个敌人会依次爆炸，对其\001\001码内的敌人造成\001\002%的伤害。",
  ["Fires a shot that pierces every enemy in a line, dealing damage. Aims at the Marked group, or else the largest group. Standing still makes it attack twice as often and its line 100% wider each sec, up to 3 times as wide."] = "发射一发贯穿直线上所有敌人的射击，造成伤害。优先瞄准被标记的敌群，其次瞄准最大的敌群。站立不动时，其攻击频率翻倍，射线宽度每秒增加\001\001%，最多可达\001\002倍宽。",
