  ["Flays the nearest enemy, dealing Shadow damage to it and half to enemies within 6 yards, applying 1 stack of Decay and slowing it by 30%."] = "鞭笞最近的敌人，对其造成暗影伤害，对其\001\001码内的敌人造成一半伤害，施加\001\002层腐朽并使其减速\001\003%。",
  ["Flays the nearest enemy, dealing Shadow damage, applying 1 stack of Decay and slowing it by 30%. When it dies, its Decay moves to your next target."] = "鞭笞最近的敌人，造成暗影伤害，施加\001\001层腐朽并使其减速\001\002%。当它死亡时，其腐朽效果会转移到你的下一个目标身上。",
