  ["Grows a ring of flowers at your feet for 4 sec. While inside, you are healed for 0.3% of your maximum health every sec, and enemies inside take Nature damage. Empowered in Tree of Life."] = "在你脚下生长一圈花环，持续\001\001秒。身处其中时，你每秒恢复\001\002%最大生命值，其中的敌人受到自然伤害。生命之树形态下获得强化。",
  ["Grunt"] = "步兵",
  ["Guardian of Cenarius"] = "塞纳留斯的守护者",
  ["Guardian of the Light"] = "圣光守卫",
  ["Gurubashi trolls, bats, tigers"] = "古拉巴什巨魔、蝙蝠、猛虎",
  ["Guts the 5 nearest enemies for heavy damage, with double critical strike chance."] = "剖开最近的\001\001个敌人，造成高额伤害，致命一击几率翻倍。",
  ["Guts the nearest enemy for heavy damage, with double critical strike chance."] = "剖开最近的敌人，造成高额伤害，致命一击几率翻倍。",
  ["Haggle"] = "讨价还价",
  ["Hail of Bolts"] = "箭矢风暴",
  ["Hallowed Ground"] = "神圣之地",
  ["Halo"] = "圣光圆环",
  ["Halo deals 5% more damage."] = "圣光圆环造成的伤害提高\001\001%。",
  ["Hammer of Justice"] = "制裁之锤",
  ["Hammer of Justice recharges 8% faster."] = "制裁之锤的充能速度加快\001\001%。",
  ["Hammer of Light"] = "光明之锤",
  ["Hammer of Wrath"] = "愤怒之锤",
  ["Hammer of the Light"] = "圣光之锤",
  ["Hammer of the Righteous"] = "正义之锤",
  ["Hammers 3 enemies and releases your Seals"] = "锤击\001\001个敌人并释放你的圣印",
  ["Hammers of light fall on 3 random enemies within 25 yards, each dealing Holy damage to every enemy within 5 yards."] = "圣光之锤砸落在\001\001码内随机的\001\002个敌人身上，每柄对其\001\003码内的所有敌人造成神圣伤害。",
  ["Hammers of light fall on 3 random enemies within 25 yards, each dealing Holy damage to every enemy within 5 yards. Every 3rd time, an extra hammer hits the largest group for triple damage within 10 yards."] = "圣光之锤砸落在\001\001码内随机的\001\002个敌人身上，每柄对其\001\003码内的所有敌人造成神圣伤害。每\001\004次会有一柄额外的战锤砸向最大的敌群，对其\001\005码内的敌人造成三倍伤害。",
  ["Hammers of light fall on 5 random enemies within 25 yards, each dealing Holy damage to every enemy within 5 yards."] = "圣光之锤砸落在\001\001码内随机的\001\002个敌人身上，每柄对其\001\003码内的所有敌人造成神圣伤害。",
  ["Hammers of light fall on the pack"] = "圣光之锤砸落在敌群中",
  ["Hand of Justice"] = "正义之手",
  ["Hand of Ragnaros"] = "拉格纳罗斯之手",
  ["Hardened"] = "百炼成钢",
  ["Hardened Foes"] = "顽敌",
  ["Haste"] = "急速",
  ["Hawk Eye"] = "鹰眼",
  ["Head Start"] = "领先起跑",
  ["Heal 100,000 health across all your runs."] = "在所有远征中累计恢复\001\001点生命值。",
  ["Heal 15,000 health with on-hit healing, such as Vampiric Embrace."] = "通过命中回血类效果（如吸血鬼的拥抱）恢复\001\001点生命值。",
  ["Heal 25,000 health across all your runs."] = "在所有远征中累计恢复\001\001点生命值。",
  ["Healed"] = "治疗量",
  ["Healing Done"] = "治疗输出",
  ["Healing Focus"] = "治疗专注",
  ["Healing Light"] = "圣光之光",
  ["Healing Rain"] = "治疗之雨",
  ["Healing Stream Totem"] = "治疗之泉图腾",
  ["Healing Tide"] = "治疗之潮",
  ["Healing past full health becomes a Shield, up to 20% of your maximum health. Health regeneration does not count."] = "溢出满生命值的治疗会转化为护盾，最多可吸收相当于\001\001%最大生命值的伤害。生命值回复不计入。",
  ["Healing that overflows into damage, a ring of light that hits far, and Decay that spreads from mind to mind."] = "溢出治疗化为伤害，圣光圆环远距打击，腐朽在心智间蔓延。",
  ["Heals that overflow into damage, and Holy Word strikes the strongest enemy."] = "溢出治疗化为伤害，圣言术打击最强敌人。",
  ["Heals you and lashes nearby enemies"] = "治疗你并抽打附近敌人",
  ["Heals you for 0.25% of your maximum health per enemy within 8 yards, up to 5 enemies. Empowered in Bear Form."] = "每秒根据\001\001码内的敌人数量为你恢复生命值，每个敌人恢复\001\002%最大生命值，最多计算\001\003个。巨熊形态下获得强化。",
  ["Heals you for 0.3% of your maximum health, and its thorny bloom lashes the 3 nearest enemies within 10 yards for Nature damage. Empowered in Tree of Life."] = "为你恢复\001\001%最大生命值，其多刺的花朵会抽打\001\002码内最近的\001\003个敌人，造成自然伤害。生命之树形态下获得强化。",
  ["Heals you for 0.3% of your maximum health. Its thorny bloom lashes the 3 nearest enemies for Nature damage. Empowered in Tree of Life."] = "为你恢复\001\001%最大生命值。其多刺的花朵会抽打最近的\001\002个敌人，造成自然伤害。生命之树形态下获得强化。",
  ["Heals you for 0.3% of your maximum health. Its thorny bloom lashes the 3 nearest enemies for Nature damage. Empowered in Tree of Life. Every 4th bloom heals you for 1% of your maximum health and deals Nature damage to all nearby enemies."] = "为你恢复\001\001%最大生命值。其多刺的花朵会抽打最近的\001\002个敌人，造成自然伤害。生命之树形态下获得强化。每\001\003次绽放会为你恢复\001\004%最大生命值，并对附近所有敌人造成自然伤害。",
  ["Heals you for 1% of your maximum health every sec. At full health, each tick smites the nearest enemy within 30 yards for Holy damage instead, jumping to 2 more nearby enemies."] = "每秒为你恢复\001\001%最大生命值。生命值全满时，每跳改为惩击\001\002码内最近的敌人，造成神圣伤害，并跳向附近\001\003个额外的敌人。",
  ["Heals you for 1% of your maximum health every sec. At full health, each tick smites the nearest enemy within 30 yards for Holy damage instead."] = "每秒为你恢复\001\001%最大生命值。生命值全满时，每跳改为惩击\001\002码内最近的敌人，造成神圣伤害。",
  ["Heals you for 1% of your maximum health every sec. At full health, each tick smites the nearest enemy within 30 yards for Holy damage instead. Any healing past full health also smites, at most twice a sec."] = "每秒为你恢复\001\001%最大生命值。生命值全满时，每跳改为惩击\001\002码内最近的敌人，造成神圣伤害。任何溢出满生命值的治疗也会进行惩击，每秒至多两次。",
  ["Heals you for each enemy close by"] = "附近敌人越多，治疗越多",
  ["Heals you, then smites at full health"] = "治疗你，生命全满时转为惩击",
