  ["Holy Shield"] = "神圣之盾",
  ["Holy Specialization"] = "神圣专精",
  ["Holy Word: Chastise"] = "圣言术：惩",
  ["Holy Word: Chastise recharges instantly when it kills an enemy."] = "圣言术：惩击杀敌人时会立即完成充能。",
  ["Holy Word: Sanctify"] = "圣言术：涤",
  ["Holy bolts at whoever struck you"] = "将神圣之箭射向攻击你的人",
  ["Holy burst around you that heals"] = "治愈你的周身神圣爆发",
  ["Holy ground and auras burn whoever comes close, while Divine Shield blocks the big hits."] = "神圣之地与光环灼烧靠近者，圣盾术则挡下重击。",
  ["Holy ground that burns enemies on it"] = "灼烧其上敌人的神圣之地",
  ["Holy light bursts around you, dealing Holy damage to every enemy within 10 yards and healing you for 0.5% of your maximum health per enemy hit, up to 3%."] = "圣光在你周围爆发，对\001\001码内的所有敌人造成神圣伤害，并每命中一个敌人为你恢复\001\002%最大生命值，最多\001\003%。",
  ["Holy light bursts around you, dealing Holy damage to every enemy within 10 yards and slowing normal enemies by 50%; Undead and Demons are stunned for 1 sec. Heals you for 0.5% of your maximum health per enemy hit, up to 3%."] = "圣光在你周围爆发，对\001\001码内的所有敌人造成神圣伤害，并使普通敌人减速\001\002%；亡灵和恶魔昏迷\001\003秒。每命中一个敌人为你恢复\001\004%最大生命值，最多\001\005%。",
  ["Holy light bursts around you, dealing Holy damage to every enemy within 14 yards and healing you for 0.5% of your maximum health per enemy hit, up to 5%."] = "圣光在你周围爆发，对\001\001码内的所有敌人造成神圣伤害，并每命中一个敌人为你恢复\001\002%最大生命值，最多\001\003%。",
  ["Holy spells deal 3% more damage."] = "神圣系法术造成的伤害提高\001\001%。",
  ["Holy strikes from afar: Exorcism, falling hammers and light that heals with every strike."] = "远程神圣打击：驱邪术、从天而降的战锤，以及随每次打击治疗你的圣光。",
  ["Hordes of Azeroth"] = "Hordes of Azeroth",
  ["Hordes of Azeroth supports Xbox and PlayStation controllers. Plug one in and press any button to play with it. There is nothing to set up."] = "Hordes of Azeroth 支持 Xbox 和 PlayStation 控制器。插上并按下任意按键即可用它游玩，无需任何设置。",
  ["Hordes of Azeroth: Shift can't dash because ClassicAPI.dll isn't loaded. Bind Dash to another key under Key Bindings instead."] = "Hordes of Azeroth：Shift 键无法用于冲刺，因为未加载 ClassicAPI.dll。请在按键设置中将冲刺绑定到其他按键。",
  ["Horns of Eranikus"] = "伊兰尼库斯之角",
  ["Hot Streak"] = "炽热连击",
  ["Hound Master"] = "猎犬首领",
  ["Houndmaster's Bow"] = "驯犬者之弓",
  ["Houndmaster's Rifle"] = "驯犬者之枪",
  ["How fast the right stick turns the camera"] = "右摇杆转动镜头的速度",
  ["Howl of the Pack Leader"] = "狼群首领之嚎",
  ["Huge Stone Club"] = "巨大石棒",
  ["Huge fireball on elites and bosses"] = "对精英和首领的巨型火球",
  ["Human"] = "人类",
  ["Hungry for More"] = "贪得无厌",
  ["Hunter"] = "猎人",
  ["Hunter's Mark"] = "猎人印记",
  ["Hunters fight using ranged weapons."] = "猎人使用远程武器战斗。",
  ["Huntmaster"] = "狩猎大师",
  ["Hurls Chain Lightning at the 2 nearest enemies, each jumping to 4 more, dealing Nature damage and 1 stack of Static to each."] = "向最近的\001\001个敌人各掷出一道闪电链，每道跳向\001\002个额外敌人，对每个敌人造成自然伤害并施加\001\003层静电。",
  ["Hurls a fiery ball at the nearest enemy, dealing Fire damage and applying 2 stacks of Burning, and plants a bomb that explodes after 2 sec for 50% damage and 2 stacks of Burning to enemies within 6 yards."] = "向最近的敌人掷出一个火球，造成火焰伤害并施加\001\001层燃烧，同时埋下一颗炸弹，在\001\002秒后爆炸，对\001\003码内的敌人造成\001\004%的伤害并施加\001\005层燃烧。",
  ["Hurls a fiery ball at the nearest enemy, dealing Fire damage and applying 2 stacks of Burning."] = "向最近的敌人掷出一个火球，造成火焰伤害并施加\001\001层燃烧。",
  ["Hurls a fiery ball at the nearest enemy, dealing Fire damage and applying 2 stacks of Burning. For 6 sec while the target lives, its Burning jumps to a nearby enemy that isn't burning every sec."] = "向最近的敌人掷出一个火球，造成火焰伤害并施加\001\001层燃烧。在目标存活的\001\002秒内，其燃烧效果每秒会跳向附近一个未燃烧的敌人。",
  ["Hurls a hammer at the strongest enemy within 20 yards, dealing Holy damage and stunning it for 2 sec. Bosses are not stunned."] = "向\001\001码内最强的敌人掷出一柄战锤，造成神圣伤害并使其昏迷\001\002秒。首领不会被昏迷。",
  ["Hurls a hammer at the strongest enemy within 20 yards, dealing Holy damage to it and every enemy within 6 yards and stunning the target for 2 sec. Bosses are not stunned."] = "向\001\001码内最强的敌人掷出一柄战锤，对其及其\001\002码内的所有敌人造成神圣伤害，并使目标昏迷\001\003秒。首领不会被昏迷。",
  ["Hurls a huge fireball at an elite or boss, or else the largest group, dealing heavy Fire damage to the target and 35% of it to enemies within 6 yards."] = "向一个精英或首领掷出巨型火球，若没有则掷向最大的敌群，对目标造成高额火焰伤害，并对其\001\001码内的敌人造成\001\002%的伤害。",
  ["Hurls hammers at the 3 strongest enemies within 20 yards, dealing Holy damage and stunning them for 2 sec. Bosses are not stunned."] = "向\001\001码内最强的\001\002个敌人掷出战锤，造成神圣伤害并使其昏迷\001\003秒。首领不会被昏迷。",
  ["Hurls hammers at up to 3 enemies below 20% health within 30 yards. Normal enemies are slain; elites and bosses take heavy Holy damage."] = "向\001\001码内最多\001\002个生命值低于\001\003%的敌人掷出战锤。普通敌人被直接击杀；精英和首领受到高额神圣伤害。",
  ["Hurls hammers at up to 3 enemies below 20% health within 30 yards. Normal enemies are slain; elites and bosses take heavy Holy damage. Each hammer also hits enemies within 5 yards for half."] = "向\001\001码内最多\001\002个生命值低于\001\003%的敌人掷出战锤。普通敌人被直接击杀；精英和首领受到高额神圣伤害。每柄战锤还会对其\001\004码内的敌人造成一半伤害。",
  ["Hurls hammers at up to 3 enemies below 35% health within 30 yards. Normal enemies are slain; elites and bosses take heavy Holy damage."] = "向\001\001码内最多\001\002个生命值低于\001\003%的敌人掷出战锤。普通敌人被直接击杀；精英和首领受到高额神圣伤害。",
  ["Hurls lava at the enemy with the most Burning, dealing Fire damage. Always critically strikes Burning enemies."] = "向燃烧层数最多的敌人掷出熔岩，造成火焰伤害。必定对燃烧中的敌人造成致命一击。",
  ["Hurls lightning at the nearest enemy that keeps jumping with no limit, dealing Nature damage and 1 stack of Static to each. Each jump deals 15% less."] = "向最近的敌人掷出闪电，闪电会无限跳转，对每个敌人造成自然伤害并施加\001\001层静电。每跳伤害降低\001\002%。",
  ["Hurls lightning at the nearest enemy, bouncing to 1 more, dealing Nature damage and 1 stack of Static to each."] = "向最近的敌人掷出闪电，并弹向\001\001个额外敌人，对每个敌人造成自然伤害并施加\001\002层静电。",
  ["Hurls lightning at the nearest enemy, dealing Nature damage and 1 stack of Static. A bolt that sets off a Static discharge also hurls a Chain Lightning from that enemy."] = "向最近的敌人掷出闪电，造成自然伤害并施加\001\001层静电。引发静电放电的闪电还会从该敌人身上再掷出一道闪电链。",
  ["Hurls lightning at the nearest enemy, jumping to 4 more, dealing Nature damage and 1 stack of Static to each."] = "向最近的敌人掷出闪电，并跳向\001\001个额外敌人，对每个敌人造成自然伤害并施加\001\002层静电。",
  ["Hurls your shield at the nearest enemy within 20 yards for damage. It jumps to 5 more enemies within 10 yards, never the same one twice. Deals 2% more damage for each 1% of your maximum health in your Shield, up to 200% more."] = "将你的盾牌掷向\001\001码内最近的敌人，造成伤害。盾牌会弹向\001\002码内的\001\003个敌人，绝不重复命中同一目标。你的护盾每相当于\001\004%最大生命值，伤害提高\001\005%，最多提高\001\006%。",
  ["Hurricane"] = "飓风",
  ["Hurricane deals 5% more damage."] = "飓风造成的伤害提高\001\001%。",
  ["Hurricane recharges 15% faster."] = "飓风的充能速度加快\001\001%。",
