  ["Ice Shards"] = "冰霜碎片",
  ["Ice follows you for 6 sec. Normal enemies within 6 yards of you are slowed by 60% and take 5% more damage."] = "寒冰随你移动\001\001秒。你\001\002码内的普通敌人减速\001\003%，受到的伤害提高\001\004%。",
  ["Ice shards on the largest group"] = "以冰片轰击最大敌群",
  ["Ice shards pelt the largest group of enemies for 4 sec, dealing Frost damage and applying 1 stack of Chill every sec."] = "冰片轰击最大的敌群，持续\001\001秒，造成冰霜伤害并每秒施加\001\002层冰寒。",
  ["Ice shards pelt the largest group of enemies for 4 sec, dealing Frost damage and applying 1 stack of Chill every sec. Each time an enemy is Frozen inside, it loses 15% of its maximum health (elites 5%, bosses 1%)."] = "冰片轰击最大的敌群，持续\001\001秒，造成冰霜伤害并每秒施加\001\002层冰寒。每当有敌人被冻结在其中，就会损失\001\003%最大生命值（精英为\001\004%，首领为\001\005%）。",
