  ["Launches 5 Arcane Missiles at the nearest enemy over 1 sec, each dealing Arcane damage. After each Blink, it fires all 5 at once at the nearest enemies and your spells deal 30% more damage for 4 sec."] = "在\001\001秒内向最近的敌人发射\001\002枚奥术飞弹，每枚造成奥术伤害。每次闪现后，会一次性向最近的敌人发射全部\001\003枚飞弹，并使你的法术伤害提高\001\004%，持续\001\005秒。",
  ["Launches 5 Arcane Missiles at the nearest enemy over 1 sec, each dealing Arcane damage. After each Blink, it fires all 5 at once."] = "在\001\001秒内向最近的敌人发射\001\002枚奥术飞弹，每枚造成奥术伤害。每次闪现后，会一次性发射全部\001\003枚飞弹。",
  ["Launches 5 Arcane Missiles at the nearest enemy over 1 sec, each dealing Arcane damage. With Blink, missiles pile up while you move instead, up to 40, and your next Blink fires them all at the nearest enemies."] = "在\001\001秒内向最近的敌人发射\001\002枚奥术飞弹，每枚造成奥术伤害。搭配闪现术时，飞弹改为在你移动时积攒，最多\001\003枚，你下一次闪现时将它们全部射向最近的敌人。",
  ["Launches a bolt of frost at the nearest enemy, dealing Frost damage and applying 1 stack of Chill, 50% more to Frozen enemies. A bolt that hits a Frozen enemy shatters it, hitting enemies within 5 yards for the same damage. Your Frost spells always critically strike Frozen enemies."] = "向最近的敌人掷出一枚冰霜箭，造成冰霜伤害并施加\001\001层冰寒，对已冻结的敌人造成的伤害提高\001\002%。命中已冻结敌人的冰霜箭会将其震碎，对\001\003码内的敌人造成等量伤害。你的冰霜法术必定对已冻结的敌人造成致命一击。",
  ["Launches a bolt of frost at the nearest enemy, dealing Frost damage and applying 1 stack of Chill, 50% more to Frozen enemies. It then jumps to the next Frozen enemy within 12 yards, up to 6 times. Your Frost spells always critically strike Frozen enemies."] = "向最近的敌人掷出一枚冰霜箭，造成冰霜伤害并施加\001\001层冰寒，对已冻结的敌人造成的伤害提高\001\002%。随后它会弹向\001\003码内下一个已冻结的敌人，最多弹射\001\004次。你的冰霜法术必定对已冻结的敌人造成致命一击。",
  ["Launches a bolt of frost at the nearest enemy, dealing Frost damage and applying 1 stack of Chill. Deals 50% more to Frozen enemies, and your Frost spells always critically strike them."] = "向最近的敌人掷出一枚冰霜箭，造成冰霜伤害并施加\001\001层冰寒。对已冻结的敌人造成的伤害提高\001\002%，且你的冰霜法术必定对其造成致命一击。",
