  ["Nightfall fires up to 3 free Shadow Bolts per sec instead of 1, and they deal 50% more damage. Your critical strike chance is reduced by 10%."] = "夜幕每秒最多触发\001\001发免费暗影箭（原为\001\002发），且其伤害提高\001\003%。你的致命一击几率降低\001\004%。",
  ["Nightmare"] = "梦魇",
