  ["None"] = "无",
  ["Normal"] = "普通",
  ["Normal enemies are frozen in place for 2 sec. Elites and bosses keep moving but count as Frozen for those 2 sec. Shatter: your Frost spells always critically strike Frozen enemies, and every critical strike against a Frozen enemy deals an extra 50% damage. After a Freeze, that enemy can't be Frozen again for 6 sec."] = "普通敌人被原地冻结\001\001秒。精英和首领仍可移动，但在\001\002秒内视同被冻结。碎裂：你的冰霜法术必定对被冻结的敌人造成致命一击，且对被冻结敌人的每次致命一击额外造成\001\003%的伤害。冻结结束后，该敌人在\001\004秒内无法再次被冻结。",
  ["Normal enemies within 8 yards flee in fear for 2 sec and take Shadow damage every sec, plus 20% more damage from everything. Elites, mini-bosses and bosses do not flee."] = "你\001\001码内的普通敌人因恐惧而逃跑，持续\001\002秒，每秒受到暗影伤害，且受到的所有伤害提高\001\003%。精英、小首领和首领不会逃跑。",
  ["Normal enemies within 8 yards flee in fear for 2 sec and take Shadow damage every sec. Elites, mini-bosses and bosses do not flee."] = "你\001\001码内的普通敌人因恐惧而逃跑，持续\001\002秒，并每秒受到暗影伤害。精英、小首领和首领不会逃跑。",
  ["Normal enemies within 8 yards flee in fear for 2 sec, gain 3 stacks of Decay and take Shadow damage every sec. Elites, mini-bosses and bosses do not flee."] = "你\001\001码内的普通敌人因恐惧而逃跑，持续\001\002秒，获得\001\003层腐朽并每秒受到暗影伤害。精英、小首领和首领不会逃跑。",
  ["Not found yet"] = "尚未找到",
  ["Not used by your class."] = "你的职业不使用此槽位。",
  ["Nothing equipped in this slot"] = "此槽位没有装备",
  ["Nothing here for this class."] = "该职业暂无内容。",
  ["Nothing here yet."] = "这里空空如也。",
  ["Nothing learned yet"] = "尚未学习任何技能",
  ["Now a Fire Elemental: it casts Fireballs that leave enemies burning, and burns enemies within 5 yards every 2 sec, applying 1 stack of Burning."] = "变为火元素：施放使敌人燃烧的火球术，并每\001\001秒灼烧\001\002码内的敌人，施加\001\003层燃烧。",
  ["Now a Water Elemental: it casts Frostbolts that apply Chill, and a small Frost Nova every 5 sec that applies 2 stacks of Chill to enemies within 6 yards."] = "变为水元素：施放施加冰寒的寒冰箭，并每\001\001秒施放一次小型冰霜新星，对\001\002码内的敌人施加\001\003层冰寒。",
  ["Now an Arcane Elemental: it casts Arcane Bolts, and a small Arcane Explosion every 3 sec that hits enemies within 6 yards."] = "变为奥术元素：施放奥术箭，并每\001\001秒施放一次小型奥术爆炸，命中\001\002码内的敌人。",
  ["Noxious Stings"] = "剧毒钉刺",
  ["Objective"] = "目标",
  ["Off"] = "关",
  ["Off Hand"] = "副手",
  ["Offered after the first timed mini-boss of a run and after every stage boss except the last. The Foresight upgrade adds one at the start of a run."] = "在远征中首个限时小首领之后以及除最后一个阶段首领外的每个阶段首领之后提供。预知升级会在远征开始时额外提供一个。",
  ["Ogremind Ring"] = "食人魔思维指环",
  ["Ogres, Witherbark trolls, Syndicate"] = "食人魔、枯木巨魔、辛迪加",
  ["Once per run, fatal damage revives you at 50% health."] = "每次远征一次：致命伤害会改为使你以\001\001%生命值复活。",
  ["Once per stage, dropping below 20% health encases you in ice: no damage taken for 2 sec, and enemies within 10 yards gain 10 Chill stacks."] = "每个阶段一次：生命值降至\001\001%以下时，你被寒冰包裹：\001\002秒内不受到任何伤害，且\001\003码内的敌人获得\001\004层冰寒。",
  ["Once per stage, dropping below 20% health grants a Shield of 30% of your maximum health."] = "每个阶段一次：生命值降至\001\001%以下时，获得一层护盾，可吸收相当于\001\002%最大生命值的伤害。",
  ["Once per stage, fatal damage restores you to full health instead."] = "每个阶段一次：致命伤害会改为将你的生命值恢复全满。",
  ["One stage in wide-open lands. Beat its boss to win the run."] = "在开阔地带进行一个阶段。击败其首领即可赢得远征。",
  ["Only appears on Heroic and Mythic."] = "仅出现在英雄和史诗难度。",
