  ["Pest Control"] = "除虫专家",
  ["Pets do the fighting: your cat bleeds the pack and the spirit wolf leads it."] = "宠物冲锋陷阵：你的猫让敌群流血，灵魂之狼统领全局。",
  ["Phase Rush"] = "相位疾走",
