  ["Physical damage over time."] = "持续物理伤害。",
  ["Pick"] = "选取",
  ["Pick a key for it under Key Bindings, Hordes of Azeroth, Use Hearthstone."] = "在按键设置的 Hordes of Azeroth 分类下，为“使用炉石”设置一个按键。",
  ["Pickup Range"] = "拾取范围",
  ["Pickup range"] = "拾取范围",
  ["Piercing Ice"] = "穿刺之冰",
  ["Places a fire trap that explodes when an enemy comes close, dealing damage and burning the ground for 4 sec, applying Burning."] = "放置一个火焰陷阱，在敌人靠近时爆炸，造成伤害并灼烧地面\001\001秒，施加燃烧。",
  ["Places a fire trap that explodes when an enemy comes close, dealing damage and burning the ground for 4 sec, applying Burning. It also scatters 5 bomblets that explode for 40% damage within 3 yards, applying Burning."] = "放置一个火焰陷阱，在敌人靠近时爆炸，造成伤害并灼烧地面\001\001秒，施加燃烧。同时散布\001\002枚子炸弹，在\001\003码内以\001\004%的伤害爆炸，施加燃烧。",
  ["Places a frost trap that goes off when an enemy comes close, slowing normal enemies inside by 60% for 6 sec. They take 5% more damage, and when the ice fades it shatters, dealing Frost damage to every enemy inside."] = "放置一个冰霜陷阱，在敌人靠近时触发，使范围内的普通敌人减速\001\001%，持续\001\002秒，受到的伤害提高\001\003%。寒冰消散时会碎裂，对范围内的所有敌人造成冰霜伤害。",
  ["Places a frost trap that goes off when an enemy comes close, slowing normal enemies inside by 60% for 6 sec. They take 5% more damage."] = "放置一个冰霜陷阱，在敌人靠近时触发，使范围内的普通敌人减速\001\001%，持续\001\002秒。它们受到的伤害提高\001\003%。",
  ["Places a trap that releases 6 venomous snakes when an enemy comes close. They bite nearby enemies for 8 sec, each bite applying 2 stacks of Poison. The snakes count as your pets."] = "放置一个陷阱，在敌人靠近时放出\001\001条毒蛇。它们会撕咬附近的敌人，持续\001\002秒，每次撕咬施加\001\003层中毒。这些毒蛇算作你的宠物。",
  ["Plague Beast"] = "瘟疫野兽",
  ["Plant Decay on the far edge of the horde and spread it from mind to mind."] = "在敌群远端种下腐朽，让它在心智间蔓延。",
  ["Plants Decay on far enemies"] = "在远处的敌人身上种下腐朽",
  ["Plants a Healing Stream Totem at your feet that heals you for 1% of your maximum health every sec while you stay within 15 yards."] = "在你脚下插入一根治疗之泉图腾，只要你停留在\001\001码内，它就会每秒为你恢复\001\002%最大生命值。",
  ["Plants a Healing Stream Totem at your feet that heals you for 1% of your maximum health every sec while you stay within 15 yards. Every 3 sec it rains on enemies within 10 yards for Nature damage."] = "在你脚下插入一根治疗之泉图腾，只要你停留在\001\001码内，它就会每秒为你恢复\001\002%最大生命值。每\001\003秒还会降雨，对\001\004码内的敌人造成自然伤害。",
  ["Plants a Magma Totem at your feet that pulses fire every 2 sec, dealing Fire damage and 1 stack of Burning to enemies within 8 yards and Dazing them."] = "在你脚下插入一根熔岩图腾，每\001\001秒喷发一次火焰，对\001\002码内的敌人造成火焰伤害并施加\001\003层燃烧，同时使其眩晕。",
  ["Plants a Magma Totem at your feet that pulses fire every 2 sec, dealing Fire damage and 1 stack of Burning to enemies within 8 yards."] = "在你脚下插入一根熔岩图腾，每\001\001秒喷发一次火焰，对\001\002码内的敌人造成火焰伤害并施加\001\003层燃烧。",
  ["Plants a Magma Totem at your feet that pulses fire every 2 sec, dealing Fire damage and 1 stack of Burning to enemies within 8 yards. Each pulse also hurls 2 globs of magma at enemies within 20 yards."] = "在你脚下插入一根熔岩图腾，每\001\001秒喷发一次火焰，对\001\002码内的敌人造成火焰伤害并施加\001\003层燃烧。每次喷发还会向\001\004码内的敌人掷出\001\005团岩浆。",
  ["Plants a Searing Totem at your feet that hurls fire at an enemy within 20 yards, applying Burning. Enemies within 15 yards of it take 15% more Fire damage."] = "在你脚下插入一根灼热图腾，向\001\001码内的一个敌人掷出火焰，施加燃烧。图腾\001\002码内的敌人受到的火焰伤害提高\001\003%。",
  ["Plants a Searing Totem at your feet that hurls fire at an enemy within 20 yards, applying Burning. Every 4 sec it bursts, dealing Fire damage and 3 stacks of Burning to enemies within 8 yards, and is replanted at your feet."] = "在你脚下插入一根灼热图腾，向\001\001码内的一个敌人掷出火焰，施加燃烧。每\001\002秒爆发一次，对\001\003码内的敌人造成火焰伤害并施加\001\004层燃烧，然后重新插到你脚下。",
  ["Plants a Searing Totem at your feet that hurls fire at an enemy within 20 yards, applying Burning. It is replanted when you move away."] = "在你脚下插入一根灼热图腾，向\001\001码内的一个敌人掷出火焰，施加燃烧。你远离时图腾会重新插到你脚下。",
  ["Play"] = "开始游戏",
  ["PlayStation"] = "PlayStation",
  ["PlayStation controller connected"] = "PlayStation 控制器已连接",
