  ["Plays a coin sound when you collect experience."] = "收集经验时播放金币音效。",
  ["Pocket Change"] = "零钱",
  ["Poison"] = "中毒",
  ["Poison damage"] = "毒性伤害",
  ["Poison on every hit, then Envenom the most poisoned enemy."] = "每次命中附带中毒，再用毒伤收割中毒最深的敌人。",
  ["Poison stings, and traps that burn or slow whatever walks in."] = "毒液钉刺，加上灼烧或减速踏入者的陷阱。",
  ["Poisoned"] = "中毒",
  ["Poisoner"] = "投毒者",
  ["Poisons the nearest enemies"] = "毒害最近的敌人",
  ["Polished Steel Boots"] = "抛光钢靴",
  ["Portals"] = "传送门",
  ["Power"] = "力量",
  ["Power Word: Barrier"] = "真言术：壁",
  ["Power Word: Fortitude"] = "真言术：韧",
  ["Power Word: Shield"] = "真言术：盾",
  ["Prayer of Mending"] = "治疗祷言",
  ["Predatory Instincts"] = "掠食本能",
  ["Prefer the classic unit frame in the top left? Under Interface Options, Your Health Bar, you can show your health there instead, or in both places."] = "更喜欢左上角的经典头像框？在界面选项的“你的生命条”中，你可以改为在那里显示你的生命值，也可以两处同时显示。",
  ["Premonition"] = "预感",
  ["Presence of Mind"] = "气定神闲",
  ["Press "] = "按",
  ["Press 'R' to change form"] = "按 R 键切换形态",
  ["Press Escape to resume."] = "按 Esc 键继续。",
  ["Press R to shift into your next form. Druid spells deal and heal 30% more in their form.|n|n|cffffffffMoonkin Form:|r Wrath strikes the nearest enemy for Nature damage, splashing nearby enemies. Every 3 sec, Starfall strikes 3 enemies afflicted by Moonfire.|n|n|cffffffffCat Form:|r Claws the nearest enemy for Physical damage and causes Bleed. Movement speed increased by 15%. Critical strikes cause Bleed.|n|n|cffffffffBear Form:|r Mauls the nearest enemy for Physical damage. Damage taken reduced by 35%, but spells of other forms deal 20% less. Swipe deals 8% more per nearby enemy. Every 6 sec, roars to Daze nearby enemies and reduce their damage by 25%.|n|n|cffffffffTree of Life:|r Vines lash 3 enemies for Nature damage, each hit healing you for 0.3% of your maximum health. Calls 1 additional Treant. Rejuvenation blooms 50% faster."] = "按R键变形为下一个形态。德鲁伊法术在对应形态下造成的伤害和治疗提高\001\001%。|n|n|cffffffff枭兽形态：|r愤怒打击最近的敌人，造成自然伤害并溅射附近敌人。每\001\002秒，星落术会打击\001\003个中了月火的敌人。|n|n|cffffffff猎豹形态：|r爪击最近的敌人，造成物理伤害并施加流血。移动速度提高\001\004%。致命一击会造成流血。|n|n|cffffffff巨熊形态：|r重殴最近的敌人，造成物理伤害。受到的伤害降低\001\005%，但其他形态的法术造成的伤害降低\001\006%。每有一个附近敌人，横扫的伤害提高\001\007%。每\001\008秒发出咆哮，使附近敌人眩晕并使其伤害降低\001\t%。|n|n|cffffffff生命之树：|r藤蔓抽打\001\n个敌人，造成自然伤害，每次命中为你恢复\001\011%最大生命值。额外召唤\001\012个树人。回春术的绽放速度加快\001\r%。",
  ["Press R to shift into your next form. Druid spells deal and heal 30% more in their form.|n|n|cffffffffMoonkin Form:|r Wrath strikes the nearest enemy for Nature damage, splashing nearby enemies. Every 3 sec, Starfall strikes 3 enemies afflicted by Moonfire.|n|n|cffffffffCat Form:|r Claws the nearest enemy for Physical damage and causes Bleed. Movement speed increased by 15%. Critical strikes cause Bleed.|n|n|cffffffffBear Form:|r Mauls the nearest enemy for Physical damage. Damage taken reduced by 35%, but spells of other forms deal 20% less. Swipe deals 8% more per nearby enemy. Every 6 sec, roars to Daze nearby enemies and reduce their damage by 25%.|n|n|cffffffffTree of Life:|r Vines lash 3 enemies for Nature damage, each hit healing you for 0.3% of your maximum health. Calls 1 additional Treant. Rejuvenation blooms 50% faster. |n|n|cffffffffShifting Surge:|r Entering a form unleashes it, once per 6 sec per form. Moonkin calls Starfall on 5 enemies, Cat causes 2 stacks of Bleed on nearby enemies, Bear roars, and Tree roots nearby enemies and heals you for 2% of your maximum health."] = "按R键变形为下一个形态。德鲁伊法术在对应形态下造成的伤害和治疗提高\001\001%。|n|n|cffffffff枭兽形态：|r愤怒打击最近的敌人，造成自然伤害并溅射附近敌人。每\001\002秒，星落术会打击\001\003个中了月火的敌人。|n|n|cffffffff猎豹形态：|r爪击最近的敌人，造成物理伤害并施加流血。移动速度提高\001\004%。致命一击会造成流血。|n|n|cffffffff巨熊形态：|r重殴最近的敌人，造成物理伤害。受到的伤害降低\001\005%，但其他形态的法术造成的伤害降低\001\006%。每有一个附近敌人，横扫的伤害提高\001\007%。每\001\008秒发出咆哮，使附近敌人眩晕并使其伤害降低\001\t%。|n|n|cffffffff生命之树：|r藤蔓抽打\001\n个敌人，造成自然伤害，每次命中为你恢复\001\011%最大生命值。额外召唤\001\012个树人。回春术的绽放速度加快\001\r%。|n|n|cffffffff变形奔涌：|r进入一个形态时释放其威力，每个形态每\001\014秒一次。枭兽召下星落打击\001\015个敌人，猎豹使附近敌人叠加\001\016层流血，巨熊发出咆哮，生命之树定身附近敌人并为你恢复\001\017%最大生命值。",
  ["Press R to shift into your next form. Druid spells deal and heal 30% more in their form.|n|n|cffffffffMoonkin Form:|r Wrath strikes the nearest enemy for Nature damage, splashing nearby enemies. Every 3 sec, Starfall strikes 3 enemies afflicted by Moonfire.|n|n|cffffffffCat Form:|r Claws the nearest enemy for Physical damage and causes Bleed. Movement speed increased by 15%. Critical strikes cause Bleed.|n|n|cffffffffBear Form:|r Mauls the nearest enemy for Physical damage. Damage taken reduced by 35%, but spells of other forms deal 20% less. Swipe deals 8% more per nearby enemy. Every 6 sec, roars to Daze nearby enemies and reduce their damage by 25%.|n|n|cffffffffTree of Life:|r Vines lash 3 enemies for Nature damage, each hit healing you for 0.3% of your maximum health. Calls 1 additional Treant. Rejuvenation blooms 50% faster. |n|n|cffffffffSpirit Forms:|r The form you leave stays behind as a spirit for 6 sec, attacking for 25% damage."] = "按R键变形为下一个形态。德鲁伊法术在对应形态下造成的伤害和治疗提高\001\001%。|n|n|cffffffff枭兽形态：|r愤怒打击最近的敌人，造成自然伤害并溅射附近敌人。每\001\002秒，星落术会打击\001\003个中了月火的敌人。|n|n|cffffffff猎豹形态：|r爪击最近的敌人，造成物理伤害并施加流血。移动速度提高\001\004%。致命一击会造成流血。|n|n|cffffffff巨熊形态：|r重殴最近的敌人，造成物理伤害。受到的伤害降低\001\005%，但其他形态的法术造成的伤害降低\001\006%。每有一个附近敌人，横扫的伤害提高\001\007%。每\001\008秒发出咆哮，使附近敌人眩晕并使其伤害降低\001\t%。|n|n|cffffffff生命之树：|r藤蔓抽打\001\n个敌人，造成自然伤害，每次命中为你恢复\001\011%最大生命值。额外召唤\001\012个树人。回春术的绽放速度加快\001\r%。|n|n|cffffffff灵魂形态：|r你离开的形态会以灵魂形态存留\001\014秒，以\001\015%的伤害继续攻击。",
