  ["Pulls every normal enemy within 12 yards of the largest group into the middle, then rains arrows on them for 3 sec, dealing damage, 5% more for each different debuff on the target. Elites and bosses resist the pull."] = "将最大的敌群周围\001\001码内的所有普通敌人拉向中央，然后向他们倾泻箭雨，持续\001\002秒并造成伤害，目标身上每种不同的减益效果都使伤害提高\001\003%。精英和首领不受牵引影响。",
