  ["Rains arrows on the largest group"] = "向最大的敌群倾泻箭雨",
  ["Rains arrows on the largest group of enemies for 3 sec, dealing damage, 5% more for each different debuff on the target."] = "向最大的敌群倾泻箭雨，持续\001\001秒并造成伤害，目标身上每种不同的减益效果都使伤害提高\001\002%。",
  ["Rains arrows on the largest group of enemies for 3 sec, dealing damage, 5% more for each different debuff on the target. The storm follows the largest group within 25 yards."] = "向最大的敌群倾泻箭雨，持续\001\001秒并造成伤害，目标身上每种不同的减益效果都使伤害提高\001\002%。风暴会跟随\001\003码内最大的敌群移动。",
  ["Rains fel fire on the 3 largest groups of enemies for 4 sec, dealing damage and applying 1 stack of Burning every sec."] = "向最大的\001\001个敌群降下邪能烈焰之雨，持续\001\002秒，造成伤害并每秒施加\001\003层燃烧。",
  ["Rains fel fire on the largest group of enemies for 4 sec, applying Burning. Each rain ends with an Infernal crashing down, dealing damage and stunning normal enemies within 6 yards for 1 sec; it then fights for 8 sec."] = "向最大的敌群降下邪能烈焰之雨，持续\001\001秒，施加燃烧。每次降雨结束时都会有一只地狱火砸落，造成伤害并使\001\002码内的普通敌人昏迷\001\003秒；随后它会为你战斗\001\004秒。",
  ["Rains fire on the largest group of enemies for 4 sec, dealing damage and applying 1 stack of Burning every sec."] = "向最大的敌群降下火焰之雨，持续\001\001秒，造成伤害并每秒施加\001\002层燃烧。",
  ["Raise a spell to rank 15 in one run."] = "在单次远征中将一个法术提升至\001\001级。",
  ["Raise a spell to rank 30 in one run."] = "在单次远征中将一个法术提升至\001\001级。",
