  ["Raise it if your hero drifts on its own"] = "如果英雄会自行漂移，请调高此值",
  ["Raises your maximum health."] = "提高你的最大生命值。",
  ["Rake"] = "斜掠",
  ["Rake rakes 1 additional enemy."] = "斜掠额外斜掠\001\001个敌人。",
  ["Rakes the 3 nearest enemies for damage and 2 stacks of Bleed. Empowered in Cat Form."] = "斜掠最近的\001\001个敌人，造成伤害并施加\001\002层流血。猎豹形态下获得强化。",
  ["Rakes the 3 nearest enemies for damage and 2 stacks of Bleed. Empowered in Cat Form. Each Rake grants 5% Haste per enemy hit for 4 sec, up to 25%."] = "斜掠最近的\001\001个敌人，造成伤害并施加\001\002层流血。猎豹形态下获得强化。每次斜掠每命中一个敌人，使你获得\001\003%急速，持续\001\004秒，最多\001\005%。",
  ["Rakes the 3 nearest enemies within 10 yards for damage and 2 stacks of Bleed. Empowered in Cat Form."] = "斜掠\001\001码内最近的\001\002个敌人，造成伤害并施加\001\003层流血。猎豹形态下获得强化。",
