  ["Rolling highlands held by ogres and outlaws. Fozruk or Prince Nazjak leads the stage."] = "被食人魔和法外之徒占据的绵延高地。弗兹鲁克或纳兹贾克王子率领着这片战场。",
  ["Roots grasp the 3 nearest enemies for Nature damage and root them for 2 sec. Empowered in Tree of Life."] = "根须缠绕最近的\001\001个敌人，造成自然伤害并使其定身\001\002秒。生命之树形态下获得强化。",
  ["Roots grasp the 3 nearest enemies for Nature damage and root them for 2 sec. Empowered in Tree of Life. Rooted enemies take Nature damage every sec, healing you for 0.05% of your maximum health each, up to 0.5% per sec."] = "根须缠绕最近的\001\001个敌人，造成自然伤害并使其定身\001\002秒。生命之树形态下获得强化。被定身的敌人每秒受到自然伤害，每有一个敌人为你恢复\001\003%最大生命值，每秒最多\001\004%。",
  ["Roots grasp the 3 nearest enemies for Nature damage and root them for 2 sec. Empowered in Tree of Life. The roots spread to nearby enemies."] = "根须缠绕最近的\001\001个敌人，造成自然伤害并使其定身\001\002秒。生命之树形态下获得强化。根须会蔓延至附近的其他敌人。",
  ["Roots grasp the 3 nearest enemies within 25 yards for Nature damage and root normal enemies for 2 sec. Empowered in Tree of Life."] = "根须缠绕\001\001码内最近的\001\002个敌人，造成自然伤害并使普通敌人定身\001\003秒。生命之树形态下获得强化。",
  ["Roots the 3 nearest enemies"] = "定身最近的\001\001个敌人",
