  ["Shapeshift"] = "变形",
  ["Shapeshift (Druid)"] = "变形（德鲁伊）",
  ["Shapeshift (R) shifts you into your next form. Each form attacks on its own; Druid spells deal and heal 30% more in their own form.|n|n|cffffffffMoonkin Form:|r Hurls Wrath at the nearest enemy, splashing 45% on enemies within 5 yards. Every 3 sec, Starfall strikes 3 different enemies with Moonfire.|n|n|cffffffffCat Form:|r Claws the nearest enemy, splashing 40% on enemies within 5 yards, and applies 1 stack of Bleed. You move 15% faster, and your critical strikes apply 1 stack of Bleed.|n|n|cffffffffBear Form:|r Mauls the nearest enemy, splashing 10% on enemies within 5 yards. You take 35% less damage, and your spells of other forms deal 20% less. Swipe deals 8% more per enemy within 8 yards, up to 64%. Every 6 sec, a roar Dazes enemies within 10 yards; they deal 25% less damage for 4 sec.|n|n|cffffffffTree of Life:|r Vines lash 3 enemies, splashing 20% on enemies within 5 yards, and each hit heals you 0.3% of your maximum health. Calls 1 additional Treant, and Rejuvenation blooms 50% faster."] = "变形（R）使你切换到下一个形态。每个形态独立攻击；德鲁伊法术在对应形态下造成的伤害和治疗提高\001\001%。|n|n|cffffffff枭兽形态：|r向最近的敌人掷出愤怒，对\001\002码内的敌人溅射\001\003%。每\001\004秒，星落术以月火打击\001\005个不同的敌人。|n|n|cffffffff猎豹形态：|r爪击最近的敌人，对\001\006码内的敌人溅射\001\007%，并施加\001\008层流血。你的移动速度提高\001\t%，致命一击会施加\001\n层流血。|n|n|cffffffff巨熊形态：|r重殴最近的敌人，对\001\011码内的敌人溅射\001\012%。你受到的伤害降低\001\r%，其他形态的法术造成的伤害降低\001\014%。\001\015码内每有一个敌人，横扫的伤害提高\001\016%，最多\001\017%。每\001\018秒发出咆哮，使\001\019码内的敌人眩晕，其伤害降低\001\020%，持续\001\021秒。|n|n|cffffffff生命之树：|r藤蔓抽打\001\022个敌人，对\001\023码内的敌人溅射\001\024%，每次命中为你恢复\001\025%最大生命值。额外召唤\001\026个树人，回春术的绽放速度加快\001\027%。",
  ["Share"] = "占比",
  ["Shared by every hero."] = "所有英雄共享。",
  ["Sharpened Claws"] = "磨利的利爪",
  ["Sharpshooter"] = "神射手",
  ["Shatter"] = "碎裂",
  ["Shatter Field"] = "碎裂领域",
  ["Shatterlord"] = "碎裂之王",
  ["Shatters frozen enemies"] = "碎裂被冻结的敌人",
  ["Shield Block"] = "盾牌格挡",
  ["Shield Block grants 2% more of your maximum health as Shield."] = "盾牌格挡提供的护盾提高，相当于最大生命值的\001\001%。",
  ["Shield Block's Shield holds up to 100% of your maximum health instead of 50% and recharges 10% per sec, even while you are struck. You deal 15% less damage."] = "盾牌格挡的护盾上限从最大生命值的\001\001%提高至\001\002%，且每秒恢复\001\003%，即使你正受到攻击也一样。你造成的伤害降低\001\004%。",
  ["Shield Slam"] = "盾牌猛击",
  ["Shield Specialization"] = "盾牌专精",
  ["Shield, % of maximum health"] = "护盾（占最大生命值的百分比）",
  ["Shields you for 10% of your maximum health and raises a dome at your feet for 5 sec; you take 25% less damage inside. Each cast tops the Shield back up instead of stacking. You move 10% faster while shielded."] = "为你施加护盾，可吸收相当于\001\001%最大生命值的伤害，并在你脚下撑起一道防护罩，持续\001\002秒；罩内你受到的伤害降低\001\003%。每次施法会将护盾补满而非叠加。持有护盾期间你的移动速度提高\001\004%。",
  ["Shields you for 10% of your maximum health; each cast tops it back up instead of stacking. You move 10% faster while shielded, and damage it absorbs is dealt back to the attacker as Holy damage."] = "为你施加护盾，可吸收相当于\001\001%最大生命值的伤害；每次施法会将护盾补满而非叠加。持有护盾期间你的移动速度提高\001\002%，且护盾吸收的伤害会以神圣伤害的形式返还给攻击者。",
  ["Shields you for 10% of your maximum health; each cast tops it back up instead of stacking. You move 10% faster while shielded."] = "为你施加护盾，可吸收相当于\001\001%最大生命值的伤害；每次施法会将护盾补满而非叠加。持有护盾期间你的移动速度提高\001\002%。",
  ["Shields, fear and binding, while Penance punishes whoever strikes you."] = "护盾、恐惧与束缚，再用苦修惩罚攻击你的人。",
  ["Shifting Surge"] = "变形奔涌",
  ["Shimmer"] = "微光",
  ["Shocks the enemy with the most Static for Nature damage, 50% more per Static stack. Consumes the stacks in a discharge that also hits up to 3 nearby enemies, and the ground shakes for 4 sec, Dazing enemies inside and dealing Nature damage every sec."] = "震击静电层数最多的敌人，造成自然伤害，每层静电使伤害提高\001\001%。消耗这些层数进行放电，还会命中最多\001\002个附近敌人，同时大地震颤\001\003秒，使其中的敌人眩晕并每秒受到自然伤害。",
  ["Shocks the enemy with the most Static for Nature damage, 50% more per Static stack. Consumes the stacks in a discharge that also hits up to 3 nearby enemies."] = "震击静电层数最多的敌人，造成自然伤害，每层静电使伤害提高\001\001%。消耗这些层数进行放电，还会命中最多\001\002个附近敌人。",
  ["Shocks the enemy with the most Static for Nature damage, 50% more per Static stack. Consumes the stacks in a discharge that also hits up to 3 nearby enemies. Every Static discharge within 10 yards of you also hits enemies within 6 yards of it."] = "震击静电层数最多的敌人，造成自然伤害，每层静电使伤害提高\001\001%。消耗这些层数进行放电，还会命中最多\001\002个附近敌人。你\001\003码内的每次静电放电还会命中其\001\004码内的敌人。",
  ["Shocks the strongest enemy nearby, elites first, dealing Fire damage and applying 6 stacks of Burning."] = "震击附近最强的敌人，优先选择精英，造成火焰伤害并施加\001\001层燃烧。",
  ["Shocks the strongest enemy nearby, elites first, dealing Fire damage and applying 6 stacks of Burning. Burning enemies that die fire a Lightning Bolt at once."] = "震击附近最强的敌人，优先选择精英，造成火焰伤害并施加\001\001层燃烧。燃烧中的敌人死亡时会立即射出一道闪电箭。",
  ["Shocks the strongest enemy nearby, elites first, dealing Frost damage and applying 6 stacks of Chill."] = "震击附近最强的敌人，优先选择精英，造成冰霜伤害并施加\001\001层冰寒。",
  ["Shooting Stars"] = "流星",
  ["Shoots from range while pets fight at your side. Marks, stings and traps set up the kill."] = "远程射击，宠物在旁作战。印记、钉刺与陷阱为杀戮铺垫。",
  ["Shoots the nearest enemy"] = "射击最近的敌人",
  ["Shoots the nearest enemy for Arcane damage and consumes all Poison on it, dealing the remaining Poison damage at once."] = "射击最近的敌人，造成奥术伤害，并消耗其身上所有中毒效果，立即造成剩余的中毒伤害。",
  ["Shoots the nearest enemy for Arcane damage, then jumps to 2 more enemies within 10 yards, Marked enemies first. Each jump deals 25% more than the last."] = "射击最近的敌人，造成奥术伤害，然后弹向\001\001码内的\001\002个敌人，被标记的敌人优先。每跳伤害比上一跳提高\001\003%。",
  ["Shoots the nearest enemy for Arcane damage."] = "射击最近的敌人，造成奥术伤害。",
  ["Shop"] = "购物",
  ["Shots, volleys and piercing arrows, with Hunter's Mark on the biggest group."] = "射击、箭雨与穿透之箭，猎人印记标记最大的敌群。",
  ["Show interact prompts"] = "显示交互提示",
  ["Shown under an enemy's bar with their stacks. On a boss's bar, each icon wipes away as its time runs out unless you hit the boss again."] = "显示在敌人血条下方，并标明层数。在首领血条上，每个图标会随时间流逝而消退，除非你再次攻击首领。",
  ["Shows health bars over enemies near you."] = "在附近的敌人上方显示血条。",
  ["Shows how much damage each of your spells has done this run."] = "显示本次远征中你的每个法术造成了多少伤害。",
  ["Shows the Hordes of Azeroth tips again from the start."] = "从头重新显示 Hordes of Azeroth 的提示。",
  ["Shows the damage you take as numbers beside your hero."] = "以数字形式在你英雄旁显示你受到的伤害。",
  ["Shows the seconds left on spells with a cooldown of 2 seconds or more."] = "显示冷却时间在\001\001秒及以上的法术的剩余秒数。",
  ["Shows your health as numbers on your health bars."] = "以数字形式在血条上显示你的生命值。",
  ["Shred"] = "撕碎",
  ["Shreds the enemy within 10 yards with the most stacks of Bleed for damage, 3% more per stack of Bleed on it, up to 30 stacks. Empowered in Cat Form."] = "撕碎\001\001码内流血层数最多的敌人，造成伤害，每层流血使伤害提高\001\002%，最多计算\001\003层。猎豹形态下获得强化。",
  ["Shreds the most Bleeding enemy for damage, increased by 3% per stack of Bleed on it. Empowered in Cat Form."] = "撕碎流血层数最多的敌人，造成伤害，目标每层流血使伤害提高\001\001%。猎豹形态下获得强化。",
  ["Shreds the most Bleeding enemy for damage, increased by 3% per stack of Bleed on it. Empowered in Cat Form. Also mangles up to 4 nearby enemies for 25% damage."] = "撕碎流血层数最多的敌人，造成伤害，目标每层流血使伤害提高\001\001%。猎豹形态下获得强化。还会撕裂最多\001\002个附近敌人，造成\001\003%的伤害。",
  ["Shreds the most Bleeding enemy for damage, increased by 3% per stack of Bleed on it. Empowered in Cat Form. If it kills, it bites the next most Bleeding enemy, up to 3 times."] = "撕碎流血层数最多的敌人，造成伤害，目标每层流血使伤害提高\001\001%。猎豹形态下获得强化。若其击杀目标，则会撕咬下一个流血层数最多的敌人，最多连续\001\002次。",
  ["Shrines"] = "神龛",
  ["Shuriken Storm"] = "手里剑风暴",
  ["Shuriken Toss"] = "手里剑投掷",
  ["Shurikens at fresh enemies"] = "将手里剑掷向新出现的敌人",
  ["Silithid swarms, Qiraji, Anubisath"] = "异种虫群、其拉人、阿努比萨斯",
  ["Silver-thread Pants"] = "银线长裤",
  ["Sinister Strike"] = "邪恶攻击",
  ["Sinister Strike deals 5% more damage."] = "邪恶攻击造成的伤害提高\001\001%。",
  ["Sinister Strike stabs 1 additional enemy."] = "邪恶攻击额外刺击\001\001个敌人。",
  ["Siphon Life"] = "生命虹吸",
  ["Skip ("] = "跳过 (",
  ["Skullsplitter Helm"] = "碎颅者头盔",
  ["Slams all enemies within 6 yards of you for damage, 2% more for each 1% of your maximum health in your Shield, up to 200% more."] = "猛击你\001\001码内的所有敌人，造成伤害，你的护盾每相当于\001\002%最大生命值，伤害提高\001\003%，最多提高\001\004%。",
  ["Slams all enemies within 6 yards of you for damage, 2% more for each 1% of your maximum health in your Shield, up to 200% more. Each enemy hit adds 1% of your maximum health to your Shield, up to 10% per slam."] = "猛击你\001\001码内的所有敌人，造成伤害，你的护盾每相当于\001\002%最大生命值，伤害提高\001\003%，最多提高\001\004%。每击中一个敌人就为你的护盾增加\001\005%最大生命值，每次猛击最多增加\001\006%。",
  ["Slams the 3 strongest enemies within 20 yards with a hammer of light for Holy damage, with double critical strike chance. Heals you for 1% of your maximum health per enemy hit, up to 5%, and releases your other Seals like Judgement."] = "以圣光之锤猛击\001\001码内最强的\001\002个敌人，造成神圣伤害，致命一击几率翻倍。每命中一个敌人为你恢复\001\003%最大生命值，最多\001\004%，并像审判一样释放你的其他圣印。",
  ["Slams the 3 strongest enemies within 20 yards with a hammer of light for Holy damage, with double critical strike chance. Judged enemies take 20% more damage from you for 6 sec. Releases your Seals like Judgement."] = "以圣光之锤猛击\001\001码内最强的\001\002个敌人，造成神圣伤害，致命一击几率翻倍。被审判的敌人在\001\003秒内受到你造成的伤害提高\001\004%。像审判一样释放你的圣印。",
  ["Slams the 3 strongest enemies within 20 yards with a hammer of light for Holy damage, with double critical strike chance. Releases your Seals: Righteousness adds 50% damage, Command hits enemies within 5 yards of each target for half, Light heals you for 1% of your maximum health per enemy hit."] = "以圣光之锤猛击\001\001码内最强的\001\002个敌人，造成神圣伤害，致命一击几率翻倍。同时释放你的圣印：正义圣印额外造成\001\003%伤害，命令圣印对每个目标\001\004码内的敌人造成一半伤害，圣光圣印每命中一个敌人为你恢复\001\005%最大生命值。",
  ["Slayer"] = "猎杀",
  ["Slays normal enemies below 20% health"] = "直接斩杀生命值低于\001\001%的普通敌人",
  ["Slays wounded enemies"] = "终结受伤的敌人",
  ["Slippery"] = "滑不留手",
  ["Slitherscale Boots"] = "蛇鳞之靴",
  ["Slow"] = "慢",
  ["Slow Time"] = "缓慢时间",
  ["Slows the enemy by 3% per stack, up to 30%. At 10 stacks the enemy becomes Frozen. An enemy that can't be Frozen yet stays at 10 stacks. Each new stack refreshes Chill to 4 sec."] = "每层使敌人减速\001\001%，最多\001\002%。叠至\001\003层时敌人被冻结。尚不能被冻结的敌人会停留在\001\004层。每层新叠加都会将冰寒的持续时间刷新为\001\005秒。",
  ["Slows the enemy by 30% for 4 sec."] = "使敌人减速\001\001%，持续\001\002秒。",
  ["Small"] = "小",
  ["Smite"] = "惩击",
  ["Smite recharges instantly when it kills an enemy."] = "惩击击杀敌人时会立即完成充能。",
  ["Smites the 2 nearest enemies"] = "惩击最近的\001\001个敌人",
  ["Smites the 2 nearest enemies for Holy damage. Each Smite takes 1 sec off Holy Word: Chastise."] = "惩击最近的\001\001个敌人，造成神圣伤害。每次惩击会使圣言术：惩的冷却时间缩短\001\002秒。",
  ["Smites the nearest enemy for Holy damage. Every 4th Smite also hits enemies within 6 yards of the target and stuns normal enemies for 1 sec. Each Smite takes 1 sec off Holy Word: Chastise."] = "惩击最近的敌人，造成神圣伤害。每\001\001次惩击中的第\001\001次还会命中目标\001\002码内的敌人，并使普通敌人昏迷\001\003秒。每次惩击会使圣言术：惩的冷却时间缩短\001\004秒。",
  ["Smites the nearest enemy with holy fire, dealing Holy damage and applying 3 stacks of Burning. Each Smite takes 1 sec off Holy Word: Chastise."] = "以圣火惩击最近的敌人，造成神圣伤害并施加\001\001层燃烧。每次惩击会使圣言术：惩的冷却时间缩短\001\002秒。",
  ["Smitten"] = "痛击斯迈特",
