  ["Spend them with Sayge at the Inn."] = "在旅店交给赛姬使用。",
  ["Spend your gold"] = "花掉你的金币",
  ["Spent at the Darkmoon vendors. You keep them between runs."] = "在暗月商人处消费。远征结束后保留。",
  ["Spiked Shield"] = "尖刺护盾",
  ["Spins for 3 sec while you keep moving, striking all enemies within 8 yards of you for damage every 0.5 sec. Haste makes it strike more often. Starting it while Enraged makes the spin last 50% longer."] = "持续旋转\001\001秒，期间你可以继续移动，每\001\002秒打击你\001\003码内的所有敌人，造成伤害。急速越高，打击越频繁。在狂怒状态下发动时，旋转持续时间延长\001\004%。",
  ["Spins through the pack, twice when Enraged"] = "旋风般穿过敌群，狂怒时旋转两次",
  ["Spins, striking all enemies within 8 yards of you for damage. Spins twice while you are Enraged."] = "旋转并打击你\001\001码内的所有敌人，造成伤害。你处于狂怒状态时会旋转两次。",
  ["Spins, striking all enemies within 8 yards of you for damage; twice while you are Enraged. Each spin leaves a storm of blades for 3 sec that strikes enemies within 8 yards for 20% damage every 0.5 sec."] = "旋转并打击你\001\001码内的所有敌人，造成伤害；你处于狂怒状态时会旋转两次。每次旋转都会留下一场刀刃风暴，持续\001\002秒，每\001\003秒对\001\004码内的敌人造成\001\005%的伤害。",
  ["Spirit"] = "活力",
  ["Spirit Bond"] = "灵魂联结",
  ["Spirit Forms"] = "灵魂形态",
  ["Spirit Healer's Regular"] = "灵魂医者的常客",
