  ["Spreads Decay from the most decayed enemy"] = "从腐朽最深的敌人处扩散腐朽",
  ["Squire"] = "侍从",
  ["Stabs the nearest enemy for damage, followed by an off-hand stab at a different enemy within 8 yards."] = "刺击最近的敌人，造成伤害，随后以副手刺击\001\001码内的另一个敌人。",
  ["Stabs the nearest enemy for damage."] = "刺击最近的敌人，造成伤害。",
  ["Stabs the nearest enemy for damage. A killing stab stabs the next nearest enemy at once, up to 3 times in a row."] = "刺击最近的敌人，造成伤害。致死的刺击会立即刺向下一个最近的敌人，最多连续\001\001次。",
  ["Stabs the nearest enemy with both daggers for damage, 3 times below 35% health, each stab applying 1 stack of Poison. Deals 30% more to Poisoned enemies."] = "双持匕首刺击最近的敌人，造成伤害，目标生命值低于\001\001%时改为刺击\001\002次，每次刺击施加\001\003层中毒。对已中毒的敌人造成的伤害提高\001\004%。",
  ["Stabs the nearest enemy with both daggers for damage, each stab applying 1 stack of Poison and 2 stacks of Nature Vulnerability. Deals 30% more to Poisoned enemies."] = "双持匕首刺击最近的敌人，造成伤害，每次刺击施加\001\001层中毒和\001\002层自然易伤。对已中毒的敌人造成的伤害提高\001\003%。",
  ["Stabs the nearest enemy with both daggers for damage, each stab applying 1 stack of Poison. Deals 30% more to Poisoned enemies."] = "双持匕首刺击最近的敌人，造成伤害，每次刺击施加\001\001层中毒。对已中毒的敌人造成的伤害提高\001\002%。",
  ["Stack Bleed on the pack, then cash it in with Mortal Strike."] = "先让敌群叠满流血，再用致死打击兑现伤害。",
  ["Stacked Deck"] = "叠好的牌堆",
  ["Stacks up to 5 times. At 5 stacks, the enemy is struck by lightning, dealing Nature damage to it and up to 3 enemies within 6 yards, and the stacks reset."] = "最多叠加\001\001次。叠至\001\002层时，闪电会击中该敌人，对其及\001\003码内最多\001\004个敌人造成自然伤害，随后层数重置。",
  ["Staff of Conjuring"] = "咒法法杖",
  ["Stage 1 takes you to any zone of "] = "第\001\001阶段会带你前往",
  ["Stage boss"] = "阶段首领",
  ["Stage bosses"] = "阶段首领",
  ["Stage {N} begins in {E}. The boss arrives in {N}."] = "第\001\001阶段将在\002\001开始。首领将于\001\002后到来。",
  ["Stampede"] = "兽群奔腾",
  ["Stand Your Ground"] = "寸步不让",
  ["Starburst"] = "星光迸发",
  ["Starcaller"] = "星辰使者",
  ["Starfall strikes in every form and hits 2 additional enemies."] = "星落术可在任何形态下施放，并额外命中\001\001个敌人。",
  ["Starfall strikes in every form and hits 2 additional enemies. Your Power is reduced by 15%."] = "星落术可在任何形态下施放，并额外命中\001\001个敌人。你的力量降低\001\002%。",
  ["Starfire"] = "星火术",
  ["Starfire deals 5% more damage."] = "星火术造成的伤害提高\001\001%。",
  ["Starlight on the strongest enemy"] = "星光打击最强敌人",
  ["Start a run"] = "开始一次远征",
  ["Start run"] = "开始远征",
  ["Start runs with +25 Valor."] = "远征开始时额外获得\001\001点勇气点数。",
  ["Starter spell"] = "起手法术",
  ["Starting zone"] = "起始地带",
  ["Static"] = "静电",
  ["Static Shock"] = "静电冲击",
  ["Static Surge"] = "静电涌动",
  ["Static discharges at 3 stacks instead of 5. You deal 15% less damage to enemies without Static."] = "静电在\001\001层时即会放电（原为\001\002层）。你对没有静电的敌人造成的伤害降低\001\003%。",
  ["Static discharges deal 8% more damage."] = "静电放电造成的伤害提高\001\001%。",
  ["Stats"] = "属性",
  ["Steady Aim"] = "稳固瞄准",
  ["Steel Cyclone"] = "钢铁气旋",
  ["Step into the Moonwell to heal ("] = "站入月亮井即可治疗（",
  ["Step through portals"] = "穿过传送门",
  ["Stick deadzone"] = "摇杆死区",
  ["Stings the nearest enemy and 2 enemies near it with 3 stacks of Poison."] = "钉刺最近的敌人及其附近的\001\001个敌人，施加\001\002层中毒。",
  ["Stings the nearest enemy and 2 enemies near it with 3 stacks of Poison. Poisoned enemies that die fire 3 venom arrows at enemies within 12 yards, each applying 2 stacks of Poison."] = "钉刺最近的敌人及其附近的\001\001个敌人，施加\001\002层中毒。中毒的敌人死亡时会向\001\003码内的敌人射出\001\004支毒箭，每支施加\001\005层中毒。",
  ["Stings the nearest enemy and 2 enemies near it with 3 stacks of Poison. Poisoned enemies that die leave a venom cloud for 2 sec that adds 1 stack of Poison every 0.5 sec to enemies within 4 yards."] = "钉刺最近的敌人及其附近的\001\001个敌人，施加\001\002层中毒。中毒的敌人死亡时会留下一团毒云，持续\001\003秒，每\001\004秒对其\001\005码内的敌人施加\001\006层中毒。",
  ["Stitched Up"] = "拆线专家",
  ["Stone Skin"] = "石肤",
  ["Stormcaller"] = "风暴召唤者",
  ["Stormlord"] = "风暴领主",
  ["Stormstrike"] = "风暴打击",
  ["Stormstrike recharges instantly when it kills an enemy."] = "风暴打击击杀敌人时会立即完成充能。",
  ["Stout Battlehammer"] = "结实战锤",
  ["Stranglethorn Vale"] = "荆棘谷",
  ["Strangling Vines"] = "勒紧藤蔓",
  ["Striker's Mark"] = "射手印记",
  ["Strikes 3 enemies and heals you"] = "打击\001\001个敌人并治疗你",
  ["Strikes 8 times over 2 sec, each strike hitting a random enemy within 10 yards for damage and carrying your poisons and openers."] = "在\001\001秒内连续攻击\001\002次，每次攻击随机命中\001\003码内的一个敌人，造成伤害并附带你的药膏和起手技。",
  ["Strikes 8 times over 2 sec, each strike hitting a random enemy within 10 yards for damage. Each kill adds 2 strikes, up to 20 more."] = "在\001\001秒内连续攻击\001\002次，每次攻击随机命中\001\003码内的一个敌人，造成伤害。每击杀一个敌人增加\001\004次攻击，最多增加\001\005次。",
  ["Strikes 8 times over 2 sec, each strike hitting a random enemy within 10 yards for damage. The last strike also fires Eviscerate and Envenom, if you hold them, without using their cooldowns."] = "在\001\001秒内连续攻击\001\002次，每次攻击随机命中\001\003码内的一个敌人，造成伤害。最后一击还会触发你的剔骨和毒伤（若你拥有它们），且不消耗其冷却时间。",
  ["Strikes all enemies within 8 yards of you for damage, 8% more per stack of Bleed on the target, up to 30 stacks."] = "打击你\001\001码内的所有敌人，造成伤害，目标每层流血使伤害提高\001\002%，最多计算\001\003层。",
  ["Strikes all enemies within 8 yards of you for damage, 8% more per stack of Bleed on the target, up to 30 stacks. 1.5 sec later the ground erupts for 30% of that damage and 1 stack of Bleed within 8 yards."] = "打击你\001\001码内的所有敌人，造成伤害，目标每层流血使伤害提高\001\002%，最多计算\001\003层。\001\004秒后地面喷发，对\001\005码内的敌人造成\001\006%的伤害并施加\001\007层流血。",
  ["Strikes all enemies within 8 yards of you for damage, 8% more per stack of Bleed on the target, up to 30 stacks. Each Bleeding enemy hit takes 0.5 sec off its cooldown, up to 1 sec per strike, down to 3 sec."] = "打击你\001\001码内的所有敌人，造成伤害，目标每层流血使伤害提高\001\002%，最多计算\001\003层。每击中一个流血的敌人，就使其冷却时间缩短\001\004秒，每次打击最多缩短\001\005秒，冷却时间最低为\001\006秒。",
  ["Strikes all enemies within 8 yards of you for damage."] = "打击你\001\001码内的所有敌人，造成伤害。",
  ["Strikes all enemies within 8 yards of you for damage. Each swing leaves an echo that strikes again 1 sec later."] = "打击你\001\001码内的所有敌人，造成伤害。每次挥击都会留下一道刀锋残影，在\001\002秒后再次打击。",
  ["Strikes all enemies within 8 yards of you for damage. Every 4th swing reaches 16 yards and knocks normal enemies back."] = "打击你\001\001码内的所有敌人，造成伤害。每\001\002次挥击中的第\001\002次可延伸至\001\003码，并击退普通敌人。",
  ["Strikes all enemies within 8 yards of you for damage. Normal enemies below 20% health die instantly; elites and bosses below 20% take triple damage. Its kills explode for 50% damage within 5 yards, executing normal enemies left below 20%. Kills Enrage you."] = "打击你\001\001码内的所有敌人，造成伤害。生命值低于\001\002%的普通敌人立即死亡；生命值低于\001\003%的精英和首领受到三倍伤害。被击杀的敌人会爆炸，对\001\004码内的敌人造成\001\005%的伤害，并斩杀其中生命值低于\001\006%的普通敌人。击杀会使你进入狂怒状态。",
  ["Strikes all enemies within 8 yards of you for damage. Normal enemies below 20% health die instantly; elites and bosses below 20% take triple damage. Kills Enrage you: 25% Haste for 4 sec."] = "打击你\001\001码内的所有敌人，造成伤害。生命值低于\001\002%的普通敌人立即死亡；生命值低于\001\003%的精英和首领受到三倍伤害。击杀会使你进入狂怒状态：急速提高\001\004%，持续\001\005秒。",
  ["Strikes all enemies within 8 yards of you for damage; elites and bosses below 20% health take triple damage. Every normal enemy within 40 yards below 20% health dies instantly. Kills Enrage you: 25% Haste for 4 sec."] = "打击你\001\001码内的所有敌人，造成伤害；生命值低于\001\002%的精英和首领受到三倍伤害。\001\003码内所有生命值低于\001\004%的普通敌人立即死亡。击杀会使你进入狂怒状态：急速提高\001\005%，持续\001\006秒。",
  ["Strikes back when you are hit"] = "你被击中时进行反击",
  ["Strikes every enemy within 8 yards"] = "打击\001\001码内的所有敌人",
  ["Strikes the 2 nearest enemies for heavy damage and 50% of it to enemies within 5 yards of each target."] = "打击最近的\001\001个敌人，造成高额伤害，并对每个目标\001\002码内的敌人造成\001\003%的伤害。",
  ["Strikes the 2 nearest enemies with fel fire, dealing damage and applying 2 stacks of Burning and 1 stack of Decay."] = "以邪能火焰打击最近的\001\001个敌人，造成伤害并施加\001\002层燃烧和\001\003层腐朽。",
  ["Strikes the 2 nearest enemies with fel fire, dealing damage and applying 2 stacks of Burning. The fire spreads to every enemy within 5 yards of each, for half damage and 1 stack of Burning."] = "以邪能火焰打击最近的\001\001个敌人，造成伤害并施加\001\002层燃烧。火焰会蔓延至每个目标\001\003码内的所有敌人，造成一半伤害并施加\001\004层燃烧。",
  ["Strikes the 2 nearest enemies with fire, dealing damage and applying 2 stacks of Burning."] = "以火焰打击最近的\001\001个敌人，造成伤害并施加\001\002层燃烧。",
  ["Strikes the 3 nearest enemies within 8 yards for damage and heals you for 0.5% of your maximum health per enemy hit, up to 2.5%. Below 50% health it strikes all enemies within 8 yards instead and heals up to 4%."] = "打击你\001\001码内最近的\001\002个敌人，造成伤害，并每命中一个敌人为你恢复\001\003%最大生命值，最多\001\004%。生命值低于\001\005%时，改为打击你\001\006码内的所有敌人，治疗量最多为\001\007%。",
  ["Strikes the 3 nearest enemies within 8 yards for damage and heals you for 0.5% of your maximum health per enemy hit, up to 2.5%. Critical strikes Enrage you: 25% Haste for 4 sec."] = "打击你\001\001码内最近的\001\002个敌人，造成伤害，并每命中一个敌人为你恢复\001\003%最大生命值，最多\001\004%。致命一击会使你进入狂怒状态：急速提高\001\005%，持续\001\006秒。",
  ["Strikes the 3 nearest enemies within 8 yards for damage and heals you for 0.5% of your maximum health per enemy hit, up to 2.5%. Healing past full health becomes a Blood Shield that explodes for 200% damage within 8 yards when it breaks."] = "打击你\001\001码内最近的\001\002个敌人，造成伤害，并每命中一个敌人为你恢复\001\003%最大生命值，最多\001\004%。溢出满生命值的治疗会转化为血盾，破碎时对\001\005码内的敌人造成\001\006%的伤害。",
  ["Strikes the 3 strongest enemies within 30 yards for heavy Holy damage. Undead and Demons take triple damage, elites and bosses double. Another Paladin spell's critical strike makes it strike at once, at most once a sec."] = "打击\001\001码内最强的\001\002个敌人，造成高额神圣伤害。亡灵和恶魔受到三倍伤害，精英和首领受到两倍伤害。你的其他圣骑士法术致命一击时，会使其立即打击一次，每秒至多一次。",
  ["Strikes the enemy with the most Bleed stacks"] = "打击流血层数最多的敌人",
  ["Strikes the enemy with the most Poison and every Poisoned enemy within 8 yards of it for Nature damage, and your hits apply 2 more stacks of Poison for 5 sec."] = "打击中毒层数最多的敌人及其\001\001码内所有已中毒的敌人，造成自然伤害，并使你的攻击在\001\002秒内额外施加\001\003层中毒。",
  ["Strikes the enemy with the most Poison for Nature damage, and your hits apply 2 more stacks of Poison for 5 sec."] = "打击中毒层数最多的敌人，造成自然伤害，并使你的攻击在\001\001秒内额外施加\001\002层中毒。",
  ["Strikes the enemy with the most Poison for Nature damage. It and every Poisoned enemy within 10 yards take the next 4 sec of their Poison damage at once, keeping their stacks. Your hits apply 2 more stacks of Poison for 5 sec."] = "打击中毒层数最多的敌人，造成自然伤害。该敌人及其\001\001码内所有已中毒的敌人会立即承受接下来\001\002秒的中毒伤害，并保留层数。你的攻击在\001\003秒内额外施加\001\004层中毒。",
  ["Strikes the most poisoned enemy"] = "打击中毒最深的敌人",
  ["Strikes the nearest enemy for heavy damage and 30% of it to enemies within 5 yards of the target."] = "打击最近的敌人，造成高额伤害，并对目标\001\001码内的敌人造成\001\002%的伤害。",
  ["Strikes the nearest enemy for heavy damage and 30% of it to enemies within 5 yards of the target. Each strike has a 15% chance to hurl a Hammer of Wrath for the same damage, slaying normal enemies below 20% health."] = "打击最近的敌人，造成高额伤害，并对目标\001\001码内的敌人造成\001\002%的伤害。每次打击有\001\003%几率掷出一柄愤怒之锤，造成等量伤害，击杀生命值低于\001\004%的普通敌人。",
  ["Strikes the nearest enemy within 12 yards twice, with weapon and lava, for damage, applying 2 stacks of Static, 2 of Nature Vulnerability and 2 of Burning. The lava deals 50% more to Burning enemies."] = "以武器和熔岩双重打击\001\001码内最近的敌人，造成伤害，施加\001\002层静电、\001\003层自然易伤和\001\004层燃烧。熔岩对燃烧中的敌人造成的伤害提高\001\005%。",
  ["Strikes the nearest enemy within 12 yards twice, with weapon and lightning, for damage, applying 2 stacks of Static and 2 stacks of Nature Vulnerability."] = "以武器和闪电双重打击\001\001码内最近的敌人，造成伤害，施加\001\002层静电和\001\003层自然易伤。",
  ["Strikes the nearest enemy within 12 yards twice, with weapon and lightning, for damage, applying 2 stacks of Static and 2 stacks of Nature Vulnerability. The lightning also hits enemies within 8 yards of you with 1 stack of Static."] = "以武器和闪电双重打击\001\001码内最近的敌人，造成伤害，施加\001\002层静电和\001\003层自然易伤。闪电还会命中你\001\004码内的敌人，施加\001\005层静电。",
  ["Strikes the strongest enemy within 30 yards for heavy Holy damage and enemies within 5 yards of it for half. Undead and Demons take triple damage, elites and bosses double. Another Paladin spell's critical strike makes it strike at once, at most once every 0.5 sec."] = "打击\001\001码内最强的敌人，造成高额神圣伤害，并对其\001\002码内的敌人造成一半伤害。亡灵和恶魔受到三倍伤害，精英和首领受到两倍伤害。你的其他圣骑士法术致命一击时，会使其立即打击一次，每\001\003秒至多一次。",
  ["Strikes the strongest enemy within 30 yards for heavy Holy damage. Undead and Demons take triple damage, elites and bosses double. Another Paladin spell's critical strike makes it strike at once, at most once a sec."] = "打击\001\001码内最强的敌人，造成高额神圣伤害。亡灵和恶魔受到三倍伤害，精英和首领受到两倍伤害。你的其他圣骑士法术致命一击时，会使其立即打击一次，每秒至多一次。",
  ["Stuns the strongest enemy"] = "使最强的敌人昏迷",
  ["Subtlety"] = "敏锐",
  ["Subtlety spells deal 3% more damage."] = "敏锐系法术造成的伤害提高\001\001%。",
  ["Succubus"] = "魅魔",
  ["Succubus deals 15% more damage."] = "魅魔造成的伤害提高\001\001%。",
  ["Sudden Death"] = "猝死",
  ["Sulfuras, Hand of Ragnaros"] = "萨弗拉斯，拉格纳罗斯之手",
  ["Summon Elemental"] = "召唤元素",
  ["Summon Infernal"] = "召唤地狱火",
  ["Summons 2 Treants that fight at your side. Their swings apply 1 stack of Moonfire, and every 6 sec a Treant's strike roots its target and normal enemies within 5 yards for 2 sec. Empowered in Tree of Life, which also calls 1 additional Treant."] = "召唤\001\001个树人在你身旁作战。它们的攻击施加\001\002层月火，并每\001\003秒定身其目标及\001\004码内的普通敌人\001\005秒。生命之树形态下获得强化，并额外召唤\001\006个树人。",
  ["Summons 2 Treants. Their attacks apply Moonfire, and every 6 sec they root their target and nearby enemies for 2 sec. Empowered in Tree of Life, which calls 1 additional Treant."] = "召唤\001\001个树人。它们的攻击会施加月火，并每\001\002秒定身其目标及附近敌人\001\003秒。生命之树形态下获得强化，并额外召唤\001\004个树人。",
  ["Summons 2 Treants. Their attacks apply Moonfire, and every 6 sec they root their target and nearby enemies for 2 sec. Empowered in Tree of Life, which calls 1 additional Treant. Their roots plant mushrooms that burst after 3 sec, dealing Nature damage to nearby enemies."] = "召唤\001\001个树人。它们的攻击会施加月火，并每\001\002秒定身其目标及附近敌人\001\003秒。生命之树形态下获得强化，并额外召唤\001\004个树人。它们的根须会种下蘑菇，在\001\005秒后爆发，对附近敌人造成自然伤害。",
  ["Summons 2 spirit wolves in fire, frost and lightning forms whose bites apply Burning, Chill or Static."] = "召唤\001\001头火焰、冰霜和闪电形态的灵魂之狼，它们的撕咬会施加燃烧、冰寒或静电。",
  ["Summons 2 spirit wolves whose bites apply Static."] = "召唤\001\001头灵魂之狼，它们的撕咬会施加静电。",
  ["Summons 2 spirit wolves whose bites apply Static. Each Windfury calls an extra wolf for 6 sec."] = "召唤\001\001头灵魂之狼，它们的撕咬会施加静电。每次唤起风怒都会召唤一头额外的狼，持续\001\002秒。",
  ["Summons a Felhunter whose Shadow Bite deals 10% more damage per affliction on the target and interrupts every caster within 8 yards of it."] = "召唤一只恶魔猎犬，其暗影撕咬的伤害随目标身上的每个诅咒效果提高\001\001%，并会打断其\001\002码内所有施法者。",
  ["Summons a Felhunter whose Shadow Bite deals 10% more damage per affliction on the target and interrupts spells. Every 10 sec it removes a harmful effect from you."] = "召唤一只恶魔猎犬，其暗影撕咬的伤害随目标身上的每个诅咒效果提高\001\001%，并可打断施法。每\001\002秒它会移除你的一个有害效果。",
  ["Summons a Felhunter whose Shadow Bite deals 10% more damage per affliction on the target and turns off an elite's affixes for 6 sec, at most once every 10 sec."] = "召唤一只恶魔猎犬，其暗影撕咬的伤害随目标身上的每个诅咒效果提高\001\001%，并会使一个精英的词缀失效\001\002秒，每\001\003秒至多触发一次。",
  ["Summons a Healing Tide Totem that walks with you and heals you for 1% of your maximum health every sec."] = "召唤一根随你移动的治疗之潮图腾，每秒为你恢复\001\001%最大生命值。",
  ["Summons a Shadowfiend whose attacks apply Decay and heal you for 0.5% of your maximum health."] = "召唤一只暗影魔，其攻击会施加腐朽，并为你恢复\001\001%最大生命值。",
  ["Summons a Shadowfiend whose attacks apply Decay and heal you for 0.5% of your maximum health. Every 6 sec it roots normal enemies within 6 yards for 2 sec."] = "召唤一只暗影魔，其攻击会施加腐朽，并为你恢复\001\001%最大生命值。它会每隔\001\002秒定身\001\003码内的普通敌人\001\004秒。",
  ["Summons a Shadowfiend whose attacks hit enemies within 5 yards of its target, apply Decay and heal you for 0.5% of your maximum health."] = "召唤一只暗影魔，其攻击会命中目标\001\001码内的敌人，施加腐朽，并为你恢复\001\002%最大生命值。",
  ["Summons a Succubus whose Lash of Pain strikes all enemies in a wide arc in front of her and applies Shadow Vulnerability."] = "召唤一个魅魔，她的痛苦之鞭会打击她前方宽广弧线范围内的所有敌人，并施加暗影易伤。",
  ["Summons a Succubus whose Lash of Pain strikes all enemies in a wide arc in front of her and applies Shadow Vulnerability. Every 8 sec she pulls the strongest normal enemy within 20 yards to her; it takes double damage for 2 sec."] = "召唤一个魅魔，她的痛苦之鞭会打击她前方宽广弧线范围内的所有敌人，并施加暗影易伤。每\001\001秒她会将\001\002码内最强的普通敌人拉到身边；该敌人受到双倍伤害，持续\001\003秒。",
  ["Summons a Succubus whose Lash of Pain strikes every enemy around her and applies Shadow Vulnerability."] = "召唤一个魅魔，她的痛苦之鞭会打击她周围的所有敌人，并施加暗影易伤。",
  ["Summons a Voidwalker that consumes enemies dying near it. After 8 it bursts in a void nova that hits every enemy around it and shields you for 5% of your maximum health."] = "召唤一个虚空行者，吞噬其附近死亡的敌人。吞噬\001\001个后，它会以虚空新星爆发，击中周围的所有敌人，并为你施加护盾，可吸收\001\002%最大生命值的伤害。",
  ["Summons a Voidwalker that consumes enemies dying near it. After 8 it bursts in a void nova that hits every enemy around it."] = "召唤一个虚空行者，吞噬其附近死亡的敌人。吞噬\001\001个后，它会以虚空新星爆发，击中周围的所有敌人。",
  ["Summons a Voidwalker that consumes enemies dying near it. After 8 it bursts in a void nova that hits every enemy around it. Every 6 sec it slams the ground within 8 yards, knocking normal enemies away."] = "召唤一个虚空行者，吞噬其附近死亡的敌人。吞噬\001\001个后，它会以虚空新星爆发，击中周围的所有敌人。它会每隔\001\002秒重击\001\003码内的地面，击退普通敌人。",
  ["Summons a three-headed hydra that spits Frost, Fire and Arcane bolts at enemies within 30 yards. Its frost head applies Chill and its fire head Burning. It follows you when you move far away."] = "召唤一条三头九头蛇，向\001\001码内的敌人喷吐冰霜、火焰和奥术箭。它的冰霜头施加冰寒，火焰头施加燃烧。你远离时它会跟随你。",
  ["Summons an Ancient of War. Every 3 sec it stomps, dealing Nature damage to nearby enemies and applying Moonfire. Empowered in Tree of Life."] = "召唤一棵战争古树。每\001\001秒它会跺地一次，对附近敌人造成自然伤害并施加月火。生命之树形态下获得强化。",
  ["Summons an Imp that hurls 2 Firebolts at a time at enemies within 30 yards, leaving them burning."] = "召唤一个小鬼，每次向\001\001码内的敌人掷出\001\002枚火球，使他们燃烧。",
  ["Summons an Imp that hurls 2 Firebolts at a time at enemies within 30 yards, leaving them burning. Enemies its Firebolts kill call a lesser Imp for 6 sec, up to 6 at once."] = "召唤一个小鬼，每次向\001\001码内的敌人掷出\001\002枚火球，使他们燃烧。被其火球击杀的敌人会召来一个小小鬼，持续\001\003秒，最多同时存在\001\004个。",
  ["Summons an Imp that hurls 2 Firebolts at a time at enemies within 30 yards, leaving them burning. Firebolts jump to 2 more enemies within 8 yards for 60% damage."] = "召唤一个小鬼，每次向\001\001码内的敌人掷出\001\002枚火球，使他们燃烧。火球会弹向\001\003码内的\001\004个额外敌人，造成\001\005%的伤害。",
  ["Summons an elemental that changes school every 5 sec: Water applies Chill, Fire applies Burning, then Arcane."] = "召唤一个元素，每\001\001秒转换一次派系：水元素施加冰寒，火元素施加燃烧，然后是奥素。",
  ["Summons an elemental to fight for you, following the school most of your spells belong to."] = "召唤一个元素为你而战，其类型与你大多数法术所属的派系一致。",
  ["Summons an undead beast to fight for you. Its Claw applies 2 stacks of Poison, and its plague cloud adds 1 stack of Poison every sec to enemies within 5 yards."] = "召唤一头亡灵野兽为你而战。它的爪击会施加\001\001层中毒，其瘟疫之云每秒对\001\002码内的敌人施加\001\003层中毒。",
  ["Summons your cat to fight for you. Its Claw applies Bleed."] = "召唤你的猫为你而战。它的爪击会施加流血。",
  ["Summons your cat to fight for you. Its Claw applies Bleed. Every 20 sec, 3 spectral beasts charge through the largest group of enemies, hitting every enemy they pass."] = "召唤你的猫为你而战。它的爪击会施加流血。每隔\001\001秒，\001\002头幽灵野兽会冲过最大的敌群，撞倒沿途的所有敌人。",
  ["Sun-baked dunes around Zul'Farrak. Gahz'rilla or Chief Ukorz Sandscalp leads the stage."] = "祖尔法拉克周围烈日灼烤的沙丘。加兹瑞拉或乌科兹\183桑斯卡普酋长率领着这片战场。",
  ["Sunder Armor"] = "破甲",
  ["Sunfire"] = "阳炎术",
  ["Suppression"] = "压制",
  ["Surefooted"] = "脚步稳健",
  ["Surge of Light"] = "光明之涌",
  ["Surrounds you with up to 3 lightning charges. An enemy that strikes you is zapped for Nature damage and 1 stack of Static, and you gain a Shield of 1% of your maximum health, up to 10%. One charge returns every 3 sec."] = "以最多\001\001层闪电充能环绕你。攻击你的敌人会被电击，受到自然伤害并叠加\001\002层静电，同时你获得一层护盾，可吸收\001\003%最大生命值的伤害，最多叠加至\001\004%。每\001\005秒恢复一层充能。",
  ["Surrounds you with up to 3 lightning charges. An enemy that strikes you is zapped for Nature damage and 1 stack of Static. One charge returns every 3 sec."] = "以最多\001\001层闪电充能环绕你。攻击你的敌人会被电击，受到自然伤害并叠加\001\002层静电。每\001\003秒恢复一层充能。",
  ["Surrounds you with up to 3 lightning charges. When an enemy strikes you or your melee hits land, a charge zaps the enemy and enemies within 4 yards for Nature damage and 1 stack of Static. One charge returns every 3 sec."] = "以最多\001\001层闪电充能环绕你。当敌人攻击你或你的近战命中时，一层充能会电击该敌人及其\001\002码内的敌人，造成自然伤害并施加\001\003层静电。每\001\004秒恢复一层充能。",
  ["Survival"] = "生存",
  ["Survival spells deal 3% more damage."] = "生存系法术造成的伤害提高\001\001%。",
  ["Survivalist"] = "生存专家",
  ["Survive 1 minute of overtime."] = "在加时中存活\001\001分钟。",
  ["Survive 2 minutes of overtime."] = "在加时中存活\001\001分钟。",
  ["Survive 6 minutes of overtime."] = "在加时中存活\001\001分钟。",
  ["Swamp of Sorrows"] = "悲伤沼泽",
  ["Swap for"] = "更换为",
  ["Swarm"] = "蜂群",
  ["Swarmer"] = "蜂拥者",
  ["Swarming"] = "蜂拥而至",
  ["Sweep"] = "横扫",
  ["Swift"] = "迅捷",
  ["Swift Justice"] = "迅捷裁决",
  ["Swift Retribution"] = "迅捷惩戒",
  ["Swiftness Potion"] = "迅捷药水",
  ["Swings at the nearest enemy for damage, adding Fire damage and 1 stack of Burning. Every 3rd swing calls Windfury: 2 extra swings that also hit enemies within 4 yards and apply 3 stacks of Burning."] = "挥击最近的敌人，造成伤害，附加火焰伤害并施加\001\001层燃烧。每\001\002次挥击中的第\001\002次会唤起风怒：额外挥击\001\003次，同时命中\001\004码内的敌人并施加\001\005层燃烧。",
  ["Swings at the nearest enemy for damage. Every 3rd swing calls Windfury: 2 extra swings that also hit enemies within 4 yards of the target."] = "挥击最近的敌人，造成伤害。每\001\001次挥击中的第\001\001次会唤起风怒：额外挥击\001\002次，同时命中目标\001\003码内的敌人。",
  ["Swings at the nearest enemy for damage. Every 3rd swing calls Windfury: 2 extra swings that also hit enemies within 4 yards. Every 15 sec, every swing calls Windfury for 4 sec."] = "挥击最近的敌人，造成伤害。每\001\001次挥击中的第\001\001次会唤起风怒：额外挥击\001\002次，同时命中\001\003码内的敌人。每隔\001\004秒，所有挥击都会唤起风怒，持续\001\005秒。",
  ["Swings with Windfury bursts"] = "挥击时爆发风怒",
  ["Swipe"] = "横扫",
  ["Swipe deals 5% more damage."] = "横扫造成的伤害提高\001\001%。",
  ["Swipe recharges 15% faster."] = "横扫的充能速度加快\001\001%。",
  ["Swipes all nearby enemies for damage. Empowered in Bear Form."] = "横扫附近的所有敌人，造成伤害。巨熊形态下获得强化。",
  ["Swipes all nearby enemies for damage. Empowered in Bear Form. Causes 1 stack of Bleed."] = "横扫附近的所有敌人，造成伤害。巨熊形态下获得强化。施加\001\001层流血。",
  ["Swipes all nearby enemies for damage. Empowered in Bear Form. Leaves a vortex for 3 sec that deals 50% damage and Dazes enemies inside every sec."] = "横扫附近的所有敌人，造成伤害。巨熊形态下获得强化。留下一个漩涡，持续\001\001秒，每秒造成\001\002%的伤害并使其中的敌人眩晕。",
  ["Swipes every enemy within 10 yards for damage. Empowered in Bear Form."] = "横扫\001\001码内的所有敌人，造成伤害。巨熊形态下获得强化。",
  ["Switched off"] = "已关闭",
  ["Switched off. It won't be offered in runs."] = "已停用。远征中不会再提供。",
  ["Switched on"] = "已开启",
  ["Sword Specialization"] = "剑类武器专精",
  ["Sword of Zeal"] = "热忱之剑",
  ["Symbols of Death"] = "死亡符记",
  ["Take 20% less damage while standing in your Consecration. Your Power is reduced by 15%."] = "站在你的奉献之地中时，受到的伤害降低\001\001%。你的力量降低\001\002%。",
  ["Take 20% less damage while you have a Shield. Your Power is reduced by 15%."] = "持有护盾期间，受到的伤害降低\001\001%。你的力量降低\001\002%。",
  ["Take 50% less healing. +20% gold."] = "受到的治疗效果降低\001\001%。金币提高\001\002%。",
  ["Taking damage drops an Explosive Trap at your feet. Once every 5 sec."] = "受到伤害时在你脚下落下一个爆炸陷阱。每\001\001秒一次。",
  ["Taking damage makes Stormstrike hit every enemy around you. Once every 6 sec."] = "受到伤害时，风暴打击会命中你周围的所有敌人。每\001\001秒一次。",
  ["Taking damage triggers Frost Nova around you. Once every 6 sec."] = "受到伤害时会触发你周围的冰霜新星。每\001\001秒一次。",
  ["Taking damage triggers Mind Blast. Once every 6 sec."] = "受到伤害时会触发心灵震爆。每\001\001秒一次。",
  ["Talent points come from Mastery levels. Right-click to refund one."] = "天赋点来自专精等级。右键点击可退还一点。",
