  ["Teleport a short distance in the direction you're moving. In midair, you teleport the way you're facing."] = "朝你移动的方向传送一小段距离。在空中时，则朝你面朝的方向传送。",
  ["Templar's Verdict"] = "圣殿骑士的裁决",
  ["That enemy is not on any run map."] = "该敌人不在任何远征地图上。",
