  ["The Challenge Altar yields its treasure!"] = "挑战祭坛献出了它的宝藏！",
  ["The Hearthstone's vault holds only 1 item. {E} will go home with you."] = "炉石的保险库只能存放\001\001件物品。\002\001将随你一起回家。",
  ["The Ley Line grants you +{N} {E} for the rest of the run."] = "在远征剩余时间内，\002\001提高\001\001点。",
  ["The Ley Line grants you +{N}% of your maximum health as a Shield for the rest of the run."] = "在远征剩余时间内，获得一层护盾，可吸收相当于你\001\001%最大生命值的伤害。",
  ["The Ley Line grants you +{N}% {E} for the rest of the run."] = "在远征剩余时间内，\002\001提高\001\001%。",
  ["The Ley Line grants you {E}!"] = "魔网赋予你\002\001！",
  ["The Light strikes the strongest enemy nearby, elites first, for heavy Holy damage and resets the cooldowns of Smite and Halo. Each Smite or Halo cast takes 1 sec off its cooldown."] = "圣光打击附近最强的敌人，优先选择精英，造成高额神圣伤害，并重置惩击和圣光圆环的冷却时间。每次施放惩击或圣光圆环都会使其冷却时间缩短\001\001秒。",
  ["The Light strikes the strongest enemy nearby, elites first, for heavy Holy damage, hits enemies within 8 yards of it for half and heals you for 5% of your maximum health. Each Smite or Halo cast takes 1 sec off its cooldown."] = "圣光打击附近最强的敌人，优先选择精英，造成高额神圣伤害，对其\001\001码内的敌人造成一半伤害，并为你恢复\001\002%最大生命值。每次施放惩击或圣光圆环都会使其冷却时间缩短\001\003秒。",
  ["The Light strikes the strongest enemy nearby, elites first, for heavy Holy damage. Each Smite or Halo cast takes 1 sec off its cooldown."] = "圣光打击附近最强的敌人，优先选择精英，造成高额神圣伤害。每次施放惩击或圣光圆环都会使其冷却时间缩短\001\001秒。",
  ["The Moonwell runs dry."] = "月亮井干涸了。",
  ["The Moonwell's waters stir! Stand in them to heal."] = "月亮井的水面泛起波澜！站在其中恢复生命。",
  ["The Scourge invades! Destroy the Necrotic Shards."] = "天灾入侵！摧毁死疽碎片。",
  ["The Scourge invasion moves on."] = "天灾入侵转移了。",
  ["The account was not wiped because a character is still left. Try again."] = "账号未被清除，因为仍有角色存在。请重试。",
  ["The account was not wiped."] = "账号未被清除。",
  ["The altar's guardians awaken!"] = "祭坛的守卫苏醒了！",
  ["The boss is already here."] = "首领已经来了。",
  ["The burning heart of Blackrock Mountain. Magmadar, Golemagg or Baron Geddon leads the stage, with Garr, Lucifron and Gehennas close behind."] = "黑石山燃烧的心脏。玛格曼达、戈勒玛格或迦顿男爵率领着这片战场，加尔、鲁西弗隆和基赫纳斯紧随其后。",
  ["The caravan is lost."] = "商队失陷了。",
  ["The caravan made it across and left you a chest!"] = "商队成功穿越，给你留下了一个箱子！",
  ["The deck is empty, so you get {M} instead."] = "牌库已空，你获得了\003\001。",
  ["The deck is empty."] = "牌库已空。",
  ["The demon portal closes."] = "恶魔传送门关闭了。",
  ["The demon portal is destroyed, leaving a chest behind!"] = "恶魔传送门被摧毁，留下了一个箱子！",
  ["The fastest single-target attacks in the game. Every stab carries a poison or an opener."] = "全游戏最快的单体攻击。每一次刺击都附带毒药或起手技。",
  ["The frozen shore of Iceflow Lake below Gnomeregan. Troggs and trolls come first, then Mekgineer Thermaplugg or the Dark Iron Ambassador and his machines."] = "诺莫瑞根之下冰流湖的冰封湖岸。穴居人和巨魔先行，麦克尼尔\183瑟玛普拉格或黑铁大使及其机器随后登场。",
  ["The game's server isn't running. Close the game and start Hordes of Azeroth with HoALauncher.exe in your World of Warcraft folder."] = "游戏服务器未运行。请关闭游戏，并使用魔兽世界文件夹中的 HoALauncher.exe 启动 Hordes of Azeroth。",
  ["The game's server stopped. Close the game and start Hordes of Azeroth again with HoALauncher.exe. If it keeps happening, click Report a bug in the launcher."] = "游戏服务器已停止。请关闭游戏，并使用 HoALauncher.exe 重新启动 Hordes of Azeroth。如果反复出现，请点击启动器中的“报告问题”。",
  ["The gold you bring back is yours to keep. Upstairs, Nix Sparkwrench sells upgrades that last through every run, "] = "你带回的金币归你所有。楼上，尼克斯\183火花扳手出售对所有远征生效的升级，",
  ["The heart of the plague, below Stratholme. Baron Rivendare and Balnazzar lead the stages."] = "斯坦索姆之下的瘟疫中心。瑞文戴尔男爵和巴纳扎尔率领着各个战场。",
  ["The interact key interacts with "] = "交互按键作用于 ",
  ["The key interacts with:"] = "该按键作用于：",
  ["The kobolds got away with your experience!"] = "狗头人带着你的经验逃跑了！",
  ["The portal has nowhere to take you right now."] = "传送门现在无处可去。",
  ["The record updates when "] = "记录会在",
  ["The rest sells for "] = "其余将售出获得 ",
  ["The ring fills in {N} seconds. Be inside it when it does to return to the Inn with your loot!"] = "法环将在\001\001秒后填满。填满时站在其中，即可带着战利品返回旅店！",
  ["The ring fills in {N} seconds. Be inside it when it does to return to the Inn. Put your best find in the Extraction Vault first!"] = "法环将在\001\001秒后填满。填满时站在其中即可返回旅店。先把最好的发现放进提取保险库！",
  ["The ruined gates of Ahn'Qiraj. Ossirian the Unscarred or Baron Kazum leads the stage."] = "安其拉的残破之门。无疤者奥斯里安或卡祖姆男爵率领着这片战场。",
  ["The server didn't answer, so the account was not wiped."] = "服务器未响应，账号未被清除。",
  ["The stage boss arrives 60 sec earlier. +15% gold."] = "阶段首领提前\001\001秒到来。金币提高\001\002%。",
  ["The temple city of the Gurubashi. Hakkar, High Priest Thekal or Bloodlord Mandokir leads the stage, with Jin'do, Venoxis and Mar'li close behind."] = "古拉巴什帝国的神庙之城。哈卡、高阶祭司塞卡尔或血领主曼多基尔率领着这片战场，金度、维诺希斯和玛尔里紧随其后。",
  ["The training dummies are whole again."] = "木桩又完好如初了。",
  ["There are no objectives right now."] = "当前没有目标。",
  ["There is no map for this place."] = "此处没有地图。",
  ["There is no room for dummies here."] = "这里没有空间放置木桩。",
  ["There is no room for it here. Step into the open and try again."] = "这里没有空间。走到开阔处再试一次。",
  ["Theron Ashveil"] = "塞隆\183灰幕",
  ["Thick Hide"] = "厚皮",
  ["Thick jungle full of Bloodscalp and Skullsplitter trolls. The Mosh'Ogg Lord or Gan'zulah leads the stage."] = "血顶部族与碎颅部族盘踞的茂密丛林。莫什奥格领主或甘祖拉率领着这片战场。",
  ["This Run"] = "本次远征",
  ["This character does not share gold or unlocks with other characters."] = "此角色不与其他角色共享金币和解锁内容。",
  ["This chest costs {N} Valor. You have {N}."] = "开启此箱子需要\001\001点勇气点数。你目前拥有\001\002点。",
  ["Thorns"] = "荆棘",
  ["Thrash"] = "痛击",
  ["Thrashes all nearby enemies for damage and 1 stack of Bleed. Empowered in Cat Form."] = "痛击附近的所有敌人，造成伤害并施加\001\001层流血。猎豹形态下获得强化。",
  ["Three stages against the deadliest foes, then Endless mode for those who dare. Gives 100% more Mastery experience."] = "连续三个阶段迎战最致命的强敌，之后是勇者专属的无尽模式。专精经验值提高\001\001%。",
  ["Throws a blade at the strongest enemy within 30 yards, elites first, for heavy damage with double critical strike chance. Normal enemies hit are slowed by 50% for 3 sec."] = "向\001\001码内最强的敌人掷出一把利刃，优先选择精英，造成高额伤害，致命一击几率翻倍。被命中的普通敌人减速\001\002%，持续\001\003秒。",
  ["Throws knives in every direction, striking all enemies within 10 yards for damage and applying 2 stacks of Poison. Also throws when Eviscerate or Envenom fires."] = "向四面八方掷出飞刀，打击\001\001码内的所有敌人，造成伤害并施加\001\002层中毒。剔骨或毒伤触发时也会掷出飞刀。",
  ["Throws knives in every direction, striking all enemies within 10 yards for damage and applying 2 stacks of Poison. Every knife carries your poisons and openers."] = "向四面八方掷出飞刀，打击\001\001码内的所有敌人，造成伤害并施加\001\002层中毒。每把飞刀都会附带你的药膏和起手技。",
  ["Throws knives in every direction, striking all enemies within 10 yards for damage and applying 2 stacks of Poison. Leaves caltrops for 4 sec that slow enemies and add 1 stack of Poison every sec."] = "向四面八方掷出飞刀，打击\001\001码内的所有敌人，造成伤害并施加\001\002层中毒。同时在地面留下铁蒺藜，持续\001\003秒，使敌人减速并每秒施加\001\004层中毒。",
  ["Throws shurikens at the 2 nearest enemies within 20 yards, ones you have not hit yet first, dealing damage. A shadow stays where each hits and bursts 1.5 sec later for Shadow damage within 5 yards."] = "向\001\001码内最近的\001\002个敌人投掷手里剑，优先攻击你尚未命中过的敌人，造成伤害。每枚命中处会留下一道暗影，在\001\003秒后爆发，对\001\004码内的敌人造成暗影伤害。",
  ["Throws shurikens at the 2 nearest enemies within 20 yards, ones you have not hit yet first, dealing damage. Each one jumps to 2 more nearby enemies."] = "向\001\001码内最近的\001\002个敌人投掷手里剑，优先攻击你尚未命中过的敌人，造成伤害。每枚手里剑会弹向\001\003个附近的其他敌人。",
  ["Throws shurikens at the 3 nearest enemies within 20 yards, ones you have not hit yet first, dealing damage."] = "向\001\001码内最近的\001\002个敌人投掷手里剑，优先攻击你尚未命中过的敌人，造成伤害。",
