  ["Wear 2 or more pieces of an epic set from the Inn's gear vendor."] = "穿戴旅店装备商人出售的史诗套装中的\001\001件或更多。",
  ["Wear it, carry it, or salvage it for Valor"] = "穿上它、带着它，或拆解它换取勇气点数",
  ["Welcome to the sandbox. Talk to the Sandbox Keeper behind you for dummies, enemies, levels and spells. Nothing here counts."] = "欢迎来到沙盒。与你身后的沙盒管理员交谈，可以召唤木桩、敌人、提升等级和学习法术。这里的一切都不作数。",
  ["Western Plaguelands"] = "西瘟疫之地",
  ["Westfall"] = "西部荒野",
  ["When a Burning enemy dies, its Burning spreads to 1 additional nearby enemy."] = "当燃烧的敌人死亡时，其燃烧会蔓延至\001\001个额外的附近敌人。",
  ["When a Poisoned enemy dies, its Poison spreads to 1 additional nearby enemy."] = "当中毒的敌人死亡时，其中毒效果会蔓延至\001\001个额外的附近敌人。",
  ["When a decaying enemy dies, its Decay spreads to 1 additional nearby enemy."] = "当腐朽的敌人死亡时，其腐朽会蔓延至\001\001个额外的附近敌人。",
  ["When an elite, mini-boss or boss dies within 30 yards, heal for 30% of your maximum health."] = "当\001\001码内有一个精英、小首领或首领死亡时，为你恢复\001\002%最大生命值。",
  ["When an enemy with your Decay or Agony dies, they jump to the nearest enemy without them, keeping every stack. Your Power is reduced by 15%."] = "当染有你的腐朽或痛苦的敌人死亡时，这些效果会连同所有层数跳转至最近一个没有该效果的敌人。你的力量降低\001\001%。",
  ["When below 35% health, heal for 30% of your maximum health. 60 sec cooldown, 15% shorter per additional copy."] = "生命值低于\001\001%时，恢复\001\002%最大生命值。冷却时间\001\003秒，每多持有一张，冷却时间缩短\001\004%。",
  ["When you are struck, strikes all enemies within 6 yards of you for damage and Enrages you (25% Haste for 4 sec), at most once every 2 sec."] = "当你受到攻击时，打击你\001\001码内的所有敌人，造成伤害，并使你进入狂怒状态（急速提高\001\002%，持续\001\003秒），每\001\004秒至多触发一次。",
  ["When you are struck, strikes all enemies within 6 yards of you for damage, at most once every 2 sec."] = "当你受到攻击时，打击你\001\001码内的所有敌人，造成伤害，每\001\002秒至多触发一次。",
  ["When you are struck, strikes all enemies within 6 yards of you for damage, at most once every 2 sec. Health damage you take is stored, up to 50% of your maximum health, and adds up to 200% damage to the next strike."] = "当你受到攻击时，打击你\001\001码内的所有敌人，造成伤害，每\001\002秒至多触发一次。你受到的生命伤害会被储存，最多储存\001\003%最大生命值，并使下一次打击的伤害提高，最多提高\001\004%。",
  ["When you drop below 50% health, run 50% faster for 4 sec. 20 sec cooldown."] = "生命值降至\001\001%以下时，移动速度提高\001\002%，持续\001\003秒。冷却时间\001\004秒。",
  ["When you would die, you come back with 40% health instead. Works once for each copy."] = "当你将要死亡时，改为以\001\001%生命值复活。每张灵魂石各生效一次。",
