  ["Your attacks and dots tick more often. Each point is worth a little less than the last, up to at most 75%."] = "你的攻击和持续伤害跳动得更频繁。每一点的效果都比上一点略低，最多\001\001%。",
  ["Your cat fights for you"] = "你的猫为你而战",
  ["Your chance for a hit to deal extra damage. Above 100%, the excess is your chance to strike critically twice."] = "你的攻击造成额外伤害的几率。超过\001\001%后，超出部分为你连续造成两次致命一击的几率。",
  ["Your chance to dodge enemy swings and take no damage."] = "你闪避敌人攻击并免受伤害的几率。",
  ["Your character"] = "你的角色",
  ["Your class's talent trees aren't available yet. The experience you earn is saved for them."] = "你的职业天赋树尚未开放。你获得的经验值会为其保留。",
  ["Your critical strikes deal 10% more damage."] = "你的致命一击造成的伤害提高\001\001%。",
  ["Your critical strikes deal 100% more damage. Your maximum health is reduced by 50%."] = "你的致命一击造成的伤害提高\001\001%。你的最大生命值降低\001\002%。",
  ["Your critical strikes make enemies Bleed"] = "你的致命一击使敌人流血",
  ["Your critical strikes wound the enemy and every enemy within 4 yards of it with 2 stacks of Bleed, at most once every 0.5 sec per enemy."] = "你的致命一击会使敌人及其\001\001码内的所有敌人受伤，施加\001\002层流血，每个敌人每\001\003秒至多触发一次。",
  ["Your critical strikes wound the enemy with 2 stacks of Bleed, at most once every 0.5 sec per enemy."] = "你的致命一击会使敌人受伤，施加\001\001层流血，每个敌人每\001\002秒至多触发一次。",
  ["Your critical strikes wound the enemy with 2 stacks of Bleed, at most once every 0.5 sec per enemy. Each tick of this Bleed deals 10% more than the last, up to triple."] = "你的致命一击会使敌人受伤，施加\001\001层流血，每个敌人每\001\002秒至多触发一次。该流血效果每跳伤害比上一跳提高\001\003%，最多提高至三倍。",
  ["Your currencies"] = "你的货币",
  ["Your dash becomes Blink and recharges twice as fast. Each Blink costs 3% of your maximum health."] = "你的冲刺变为闪现术，充能速度加倍。每次闪现消耗\001\001%最大生命值。",
  ["Your dash becomes Blink, teleporting you, with 1 more charge and 30% faster recharge. Each Blink sets off an Arcane Explosion where you leave, dealing Arcane damage to enemies within 10 yards. Takes a spell slot."] = "你的冲刺变为闪现术，可传送你自身，充能次数增加\001\001次，充能速度提高\001\002%。每次闪现都会在你离开的位置引发一次奥术爆炸，对\001\003码内的敌人造成奥术伤害。占用一个法术槽位。",
  ["Your dash becomes Blink, with 1 more charge and 30% faster recharge. Each Blink sets off an Arcane Explosion where you leave, dealing Arcane damage to enemies within 10 yards, hits every enemy along your path and makes you immune to damage for 1 sec."] = "你的冲刺变为闪现术，充能次数增加\001\001次，充能速度提高\001\002%。每次闪现都会在你离开的位置引发一次奥术爆炸，对\001\003码内的敌人造成奥术伤害，命中沿途的所有敌人，并使你免疫伤害\001\004秒。",
  ["Your dash becomes Blink, with 3 more charges and 30% faster recharge. Each Blink sets off an Arcane Explosion where you leave, dealing Arcane damage to enemies within 10 yards, and resets your Arcane Explosion spell."] = "你的冲刺变为闪现术，充能次数增加\001\001次，充能速度提高\001\002%。每次闪现都会在你离开的位置引发一次奥术爆炸，对\001\003码内的敌人造成奥术伤害，并重置你的奥术爆炸法术。",
  ["Your dash recharges 10% faster."] = "你的冲刺充能速度加快\001\001%。",
  ["Your dash teleports and explodes"] = "你的冲刺变为传送并引发爆炸",
  ["Your debuffs"] = "你的减益效果",
  ["Your demons deal 10% more damage for each different demon you command, up to 40%. Your Power is reduced by 15%."] = "你每指挥一种不同的恶魔，你所有恶魔造成的伤害就提高\001\001%，最多提高\001\002%。你的力量降低\001\003%。",
  ["Your first hit on each enemy ambushes it"] = "你对每个敌人的首次命中都会发动伏击",
  ["Your first hit on each enemy with your other abilities is followed by an Ambush for heavy damage, with double critical strike chance."] = "你的其他技能对每个敌人的首次命中之后，会发动一次伏击，造成高额伤害，致命一击几率翻倍。",
  ["Your first hit on each enemy with your other abilities is followed by an Ambush for heavy damage, with double critical strike chance. Ambush stuns normal enemies for 1 sec."] = "你的其他技能对每个敌人的首次命中之后，会发动一次伏击，造成高额伤害，致命一击几率翻倍。伏击会使普通敌人昏迷\001\001秒。",
  ["Your first hit on each enemy with your other abilities is followed by an Ambush for heavy damage, with double critical strike chance. Ambushed enemies take 20% more damage from you for 6 sec."] = "你的其他技能对每个敌人的首次命中之后，会发动一次伏击，造成高额伤害，致命一击几率翻倍。被伏击的敌人在\001\001秒内受到你造成的伤害提高\001\002%。",
  ["Your health bar:"] = "你的生命条：",
  ["Your hero can "] = "你的英雄可以",
  ["Your hits apply Poison"] = "你的攻击施加中毒",
  ["Your hits deal 30% more damage for 4 sec and can set off Ambush again, once a sec per enemy."] = "在\001\001秒内你的攻击造成的伤害提高\001\002%，且可再次触发伏击，每个敌人每秒一次。",
  ["Your hits deal 30% more damage for 4 sec and can set off Ambush again, once a sec per enemy. Starts with a shadow strike on the 5 strongest enemies within 20 yards for damage."] = "在\001\001秒内你的攻击造成的伤害提高\001\002%，且可再次触发伏击，每个敌人每秒一次。发动时先以暗影打击\001\003码内最强的\001\004个敌人，造成伤害。",
  ["Your hits deal 30% more damage for 4 sec and can set off Ambush again, once a sec per enemy. Starts with a vanish: normal enemies within 10 yards lose you and stand dazed for 2 sec."] = "在\001\001秒内你的攻击造成的伤害提高\001\002%，且可再次触发伏击，每个敌人每秒一次。发动时先消失一次：\001\003码内的普通敌人会丢失你的踪影并眩晕\001\004秒。",
  ["Your hits deal extra Holy damage"] = "你的打击造成额外神圣伤害",
  ["Your hits have a 1% chance to deal 10 times their damage."] = "你的攻击有\001\001%几率造成\001\002倍伤害。",
  ["Your hits have a 10% chance to heal you for 1% of your maximum health, up to 0.3% per second."] = "你的攻击有\001\001%几率为你恢复\001\002%最大生命值，每秒最多\001\003%。",
  ["Your hits have a 3% chance to deal 150% of the hit as Fire within 6 yards."] = "你的攻击有\001\001%几率造成\001\002%的火焰伤害，波及\001\003码内的敌人。",
  ["Your hits have a 3% chance to strike 3 enemies with lightning for 100% of the hit."] = "你的攻击有\001\001%几率以闪电打击\001\002个敌人，造成\001\003%的伤害。",
  ["Your hits have a 5% chance to deal 200% of the hit as Shadow within 8 yards, healing you for 10% of the damage."] = "你的攻击有\001\001%几率造成\001\002%的暗影伤害，波及\001\003码内的敌人，并为你恢复其伤害\001\004%的生命值。",
  ["Your hits have a 6% chance to cast Chain Lightning, striking 5 enemies for 150% of the hit."] = "你的攻击有\001\001%几率施放闪电链，打击\001\002个敌人，造成\001\003%的伤害。",
  ["Your hits have a 6% chance to deal 200% of the hit as Fire within 8 yards."] = "你的攻击有\001\001%几率造成\001\002%的火焰伤害，波及\001\003码内的敌人。",
  ["Your hits strike 4 more enemies"] = "你的攻击额外打击\001\001个敌人",
  ["Your last 10 seconds"] = "你的最后\001\001秒",
  ["Your next level-up offers an evolution for a spell at rank 10 or higher. Used up once offered."] = "你下次升级时，会为一个等级达到\001\001级或以上的法术提供进化选项。提供一次后即消耗。",
  ["Your other abilities apply 1 stack of Poison with every hit and deal 30% extra as Nature damage."] = "你的其他技能每次命中都会施加\001\001层中毒，并额外造成\001\002%的自然伤害。",
  ["Your other abilities apply 1 stack of Poison with every hit and slow normal enemies by 30%. Poisoned enemies take 15% more damage from you."] = "你的其他技能每次命中都会施加\001\001层中毒，并使普通敌人减速\001\002%。已中毒的敌人受到你造成的伤害提高\001\003%。",
  ["Your other abilities apply 1 stack of Poison with every hit."] = "你的其他技能每次命中都会施加\001\001层中毒。",
  ["Your own health, shown over your hero. A bright cyan glow on it is your Shield."] = "你自己的生命值，显示在英雄上方。上面的亮青色光晕是你的护盾。",
  ["Your pets are always frenzied: +50% damage, and their attacks hit every enemy in front of them. Your other spells deal 30% less damage."] = "你的宠物始终处于狂热状态：造成的伤害提高\001\001%，且它们的攻击会命中它们前方的所有敌人。你的其他法术造成的伤害降低\001\002%。",
  ["Your pets inherit 5% more of your Power while Pack Leader is out."] = "狼群首领在场时，你的宠物继承的力量提高\001\001%。",
  ["Your route"] = "你的路线",
  ["Your run starts here. Later stages are random."] = "你的远征从这里开始。后续阶段随机。",
  ["Your runs start with this spell."] = "你的远征以此法术开局。",
  ["Your saved piece"] = "你保存的装备",
  ["Your shots target Marked enemies first and deal 40% more damage to them. Unmarked enemies take 25% less damage from you."] = "你的射击优先瞄准被标记的敌人，并对其造成的伤害提高\001\001%。未被标记的敌人受到你造成的伤害降低\001\002%。",
  ["Your single-target hits also strike 1 enemy within 8 yards for 50% damage, even without Blade Flurry. Your critical strike chance is reduced by 10%."] = "即使没有剑刃乱舞，你的单体攻击也会以\001\002%的伤害打击\001\001码内的\001\003个敌人。你的致命一击几率降低\001\004%。",
  ["Your single-target hits also strike 4 more enemies within 8 yards at 50% damage as Shadow damage for 8 sec. Extra hits can set off Ambush again, once a sec per enemy."] = "在\001\001秒内，你的单体攻击还会以暗影伤害打击\001\002码内的\001\003个额外敌人，伤害为\001\004%。额外攻击可再次触发伏击，每个敌人每秒一次。",
  ["Your single-target hits also strike 4 more enemies within 8 yards at 50% damage for 8 sec. The extra hits carry your poisons and openers."] = "在\001\001秒内，你的单体攻击还会以\001\002%的伤害打击\001\003码内的\001\004个额外敌人。额外攻击会附带你的药膏和起手技。",
  ["Your single-target hits always strike 1 more enemy within 8 yards at 50% damage. The extra hits carry your poisons and openers."] = "你的单体攻击始终会以\001\001%的伤害额外打击\001\002码内的\001\003个敌人。额外攻击会附带你的药膏和起手技。",
  ["Your spells fire more bolts or shots, swing more times, and place or summon more. AoE spells are not affected."] = "你的法术会射出更多法弹或箭矢、挥击更多次、放置或召唤更多单位。范围法术不受影响。",
  ["Your spells have a 10% chance to cast twice."] = "你的法术有\001\001%几率施放两次。",
